"""Individually authored readability edits. Source ledger and audience stay intact."""
import copy,hashlib,json,re
from pathlib import Path
HERE=Path(__file__).resolve().parent
original=json.loads((HERE/'body-input.json').read_text(encoding='utf-8'))['entries']
by_id={e['id']:e for e in original}
edits={}
def add(eid,title,summary,plain,benefit=None,notes=None):
    e=by_id[eid]
    def refs(value):return re.sub(r'\[@(\d+)\]',lambda m:'[@'+e['source_ids'][int(m[1])]+']',value)
    fields=copy.deepcopy(e['fields']);fields['plain']=refs(plain)
    if benefit is not None:fields['benefit']=refs(benefit)
    if notes is not None:fields['notes']=refs(notes)
    edits[eid]=dict(id=eid,title=title,summary=summary,fields=fields,audit=dict(full_original_fields_read=True,approach='按本条概念、证据和动作重新组织；急症动作前置。',source_tokens_preserved=True,audience_unchanged=True,new_medical_claims=False))

add('neck-001','颈肩痛伴手越来越无力或走不稳，尽快检查',
'颈肩痛同时出现扣纽扣困难、频繁掉东西、手越来越无力或走路不稳，需要尽快检查神经和脊髓。新出现大小便失控、重外伤后剧痛应急诊；手臂突然无力又脸歪、说话不清，立即拨120，即使随后好转也别等。',
'**手越来越无力、扣纽扣变难、常掉东西或走不稳，尽快到骨科、脊柱或神经专科检查。** 不要先按摩、扳颈。新出现大小便控制变化、肢体迅速无力，或重外伤后颈部剧痛，走急诊。[@0][@1]\n\n颈部神经根连接手臂，脊髓传递更广泛的运动和感觉信号，受影响时未必只有颈痛。医生需结合力量、感觉、手指动作和步态判断是否做影像，不能靠“揉开压住的神经”处理。[@0][@1]\n\n若手臂无力突然发生，尤其伴脸歪、说话不清，**立即拨120，不自行开车**；几分钟后恢复仍需急救评估。[@2]',benefit='及早处理可能影响神经或脊髓功能的问题。')
add('neck-002','普通落枕温和活动，转头受限时别开车',
'没有外伤、发热或神经异常的落枕，可先减少负重和持续低头，在耐受范围内活动头颈。不要硬拉或自行长期戴颈托。转头受限时暂停开车、骑车；数周不改善、不断加重或新出现麻木无力，需要复查。',
'落枕通常表现为睡醒后颈部僵痛；先排查[外伤、神经或全身异常](#/entry/neck-001)，再决定是否居家处理。没有这些信号的急性非特异性颈痛，不需常规先拍片，检查要由病史和体检决定。[@2]\n\n**减少负重与持续低头，把电脑、家务分段做，轻轻转头和活动肩膀。** 不用手把头拉到底，也不自行长期戴颈托。无需等完全不痛才恢复日常任务，但出现明显加重、新麻木或无力时应停下复评。[@0][@1]\n\n转头受限会妨碍观察路况，恢复前别开车或骑车。数周仍不改善、止痛措施无效或越来越痛，安排检查；骨折、术后等已要求固定者仍按原方案。[@0]',benefit='逐步恢复日常活动，避免长期固定或延误检查。')
add('neck-003','调好屏幕和键鼠，久坐时换姿势、起来活动',
'先把屏幕放到正前方，键鼠移到不必耸肩、伸手的位置，避免手腕压在硬桌边。长期用笔记本，抬高屏幕时通常也需外接键鼠。再好的工位也不能抵消整天不动；买椅子、升降桌或矫姿带前，先看它解决了哪个具体问题。',
'工位调整是减少持续低头、伸手和局部压迫，不是把身体锁在一个“标准坐姿”。职业卫生和康复指导支持舒适支撑与任务变化，但不能据“人体工学”四个字证明某款椅子能治颈椎病。[@0][@1]\n\n先改现有桌面：屏幕正对身体，上缘约在眼高或稍低；键鼠靠近，肩膀能放松；前臂和手腕别压在硬桌沿。笔记本抬高后配外接键鼠，避免低头变成抬肩打字。[@0]\n\n**定期起身走动、换任务、轻活动肩臂。** 没有人人必须遵守的最佳间隔。买椅子或支架时，只为实际的够不到、悬空、压迫或看不清的问题付费；矫姿带不能代替活动与检查。[@0][@1]',benefit='降低持续负担，让工作位置适合自己的任务与体型。')
add('neck-004','睡醒总颈痛，先调枕头支撑和睡姿',
'枕头是否合适，要看实际躺下后头颈是否有支撑、是否明显弯折。先整理现有枕芯或试少量毛巾辅助，再决定更换；乳胶、记忆棉或某个高度都不是通用答案。持续夜痛、手麻无力或反复影响睡眠，需要查原因。',
'枕头能改变夜间支撑和舒适，不能承诺把椎间盘或受压神经“睡回去”。侧卧、仰卧的需要不同，没有同一材质或厘米数适合所有人；NHS建议避免趴睡或长时间扭着颈部。[@0][@1]\n\n**在平时的床上试躺：头与躯干大致对齐，颈部不悬空，也不被顶得明显弯折。** 可先整理枕芯，或用小毛巾卷辅助颈部凹陷处。能调节、试躺舒服且回家后睡得合适，比“医学曲线”宣传更有用。[@0]\n\n不必整夜固定姿势、禁止翻身。夜痛持续加重、出现手麻无力，或调整后仍反复影响睡眠，应检查病因；术后有固定要求者按原方案。',benefit='改善夜间舒适，减少反复买枕头却没查病因的试错。')
add('neck-007','反复颈肩痛，逐步恢复活动和力量',
'慢性颈肩痛的重点是恢复工作、抬手、提物和睡觉等能力，不能每次只靠按摩暂时舒服。排除需要单独治疗的病因后，按耐受练活动度、力量与耐力。新出现麻木无力、明显放射痛或功能变差，停止训练并复评。',
'非特异性颈痛指没有明确的其他病因解释的颈部疼痛；不能仅凭“经常酸”给自己确诊。2025指南把主动活动与教育放在治疗中心，慢性问题尤其需要运动，而非只做被动疗程。[@0]\n\n先说清最难的任务：久坐、抬手、提包还是睡觉。再让康复人员教会活动度、力量和耐力动作，以及负荷如何调整。**从短、轻、能坚持开始，逐步加回任务，不必长期完全停用手臂。**[@1]\n\n牵拉感不代表越痛越有效。不要强拉、快速甩头，或带着新麻木无力继续练；头晕、明显放射痛、功能变差时停下复评。[@2]',benefit='以恢复日常能力为目标，减少只靠理疗的反复循环。')
add('neck-005','肩颈冷热敷要隔布，别带着敷袋睡觉',
'冷热敷只能短时缓解疼痛，不是越热、越冰或越久越好。敷前确认皮肤、感觉和循环正常，隔布并随时看皮肤；灼痛、发白发蓝或异常麻木立即移开。外用药贴能否加热要看说明，感觉减退者不要自行尝试。',
'冷热敷的作用是暂时舒适，帮助活动，不是把神经“烫开”。僵紧酸痛可试温和热敷；近期受伤后肿热，冷敷可短时缓解，但不能替代外伤检查。[@0][@1]\n\n**敷袋隔布，只用于皮肤完整、感觉和循环正常处。** NHS颈痛页举例冷敷5分钟、热敷20分钟；不同部位、产品不可直接套同一上限。过程中看皮肤，灼痛、发白发蓝或异常麻木就移开，待皮肤温度恢复再考虑下一次。[@0][@1]\n\n不要边敷边睡。药贴、外用止痛品能否加热，先看标签；辣椒素类须避开加热垫等直接热源。感觉减退、循环异常或不能及时表达不适者先问医护，不能凭家属摸着不烫保证安全。[@2][@1]',benefit='缓解一时不适，同时减少热损伤或冻伤。')
add('neck-006','肩颈痛要用药，先查成分，别重复叠加',
'止痛药能帮助短期活动，但口服药、贴膏、凝胶和感冒药可能有重复成分。布洛芬与对乙酰氨基酚的风险不同，胃溃疡、肝肾病、心血管病、孕哺及并用药都会影响选择。疼痛恶化或总要加量才能工作，应重新查原因。',
'布洛芬属于非甾体抗炎药（NSAID），能止痛，也有胃肠出血、肾脏等风险。对乙酰氨基酚是另一类止痛成分，过量可伤肝；“不同牌子”不代表能安全叠吃。[@0][@1]\n\n**把口服药、凝胶、药贴和感冒药的有效成分列在一起，选合适的短期方案。** 不随意叠加同类口服NSAID；对乙酰氨基酚要防复方感冒药重复。胃溃疡、肝肾或心血管病、抗凝治疗、过敏、饮酒及孕哺情况，交给医生或药师一起判断。用量按手中药品的国内说明书，不照搬其他规格。[@0][@1]\n\n外用药不涂破皮，避开眼口，不擅自加热或多层叠贴。止痛是为必要活动服务；越来越痛、出现[危险信号](#/entry/neck-001)或总靠加量硬撑，转为检查和康复。[@0][@2]',benefit='需要时获得止痛，减少重复制剂与相互作用风险。')
add('neck-008','按摩可求放松，别靠强力扳颈“复位”',
'按摩后轻松，不等于颈椎复位或神经压迫已经治好。持续颈痛的研究对按摩额外疗效仍不确定。轻柔按摩与快速扳颈是不同操作；别按疼痛、瘀青或响声判断效果，做完新出现剧烈头颈痛、视物或说话异常，应急诊。',
'轻柔按摩主要作用于软组织；快速扳颈是另一种手法。2024 Cochrane综述发现，亚急性或持续性颈痛与假按摩相比，约12周额外获益仍不明确、证据确定性低，也没有研究急性颈痛。[@0]\n\n颈部手法存在罕见严重事件和动脉夹层报告，即动脉壁层间异常分离；发生率和因果关系仍不清楚，不能因此省掉事前评估与风险说明。[@1]\n\n**想短时放松，先排除外伤和神经异常，要求轻柔、可随时停止。** 不让朋友照视频猛扳，不接受“复位就不用检查”。选择专业手法时问清目标、替代办法和复评时间，同时保留主动训练。做完新发剧烈头颈痛、说话或视物异常、单侧无力，直接急诊。[@1][@2]',benefit='保留可接受的放松体验，不让“复位”承诺延误治疗。')
add('neck-009','慢性颈痛试针灸，要配合活动并复评效果',
'针灸可作为部分慢性非特异性颈痛的辅助选择，不能替代主动训练，也不是急性落枕的常规起步治疗。先定一个可观察的目标，如转头或睡觉是否改善，再决定是否继续。选择合规医疗机构，说明出血风险用药、基础病和孕哺情况。',
'针灸是用细针刺激皮肤等组织的医疗操作，不等于按摩。2025指南对排除危险病因的慢性非特异性颈痛，允许在主动活动之外有条件提供针灸；没有将它作为急性颈痛的常规起步治疗。[@0]\n\n研究中，与不治疗的差异常大于与假针的差异，不能保证个人会大幅或长期改善；腰痛试验也不能直接当作颈痛证据。[@1]\n\n**尝试前选定目标和复评时间：睡眠、工作或转头是否改善。** 效果未达目标就重评，不无限续疗程。到有资质的医疗机构接受规范无菌操作，主动说明抗凝等出血风险药物、基础病与孕哺；别在家扎针，也别用它拖延新发神经症状的检查。[@1]',benefit='多一种有条件的症状管理选择，同时知道何时停止试错。')
add('neck-010','筋膜枪只轻打肌肉，别敲颈前侧和脊柱',
'筋膜枪靠快速敲击让部分人短时放松，不是排乳酸、纠正姿态或治疗颈椎病的必需品。若要用，从明确的肌肉区域低强度短时开始，轻轻移动；疼或麻就停。颈前侧、脊柱、关节、新伤肿痛处不要敲，部位拿不准就换温和活动。',
'筋膜枪是快速往复敲击设备。现有综述研究少、偏倚明显，短期活动度或柔韧变化不能证明治好颈椎病、纠正姿态或长期防伤，也不支持为“排乳酸”追高档设备。[@0]\n\n**只在能明确辨认的肩背肌肉上，按说明低强度、短时间轻移。** 不压着一点硬打；疼痛、麻木或皮肤红痛就停。避开脊柱骨突、关节、神经走行、新伤肿痛处，尤其不自助敲颈前侧血管区。骨质疏松、感觉异常、基础病或相关用药者先评估。[@1][@2]\n\n少量血管损伤报告不能算个人发生率，但后果足以要求谨慎。酸痛还可用温和活动、轻揉或合适冷热敷；敲后出现神经异常，按[急症入口](#/entry/neck-001)处理。[@2]',benefit='可能短时放松，避免把敲击误当结构治疗。')
add('neck-011','肩膀抬不起来，外伤后突然发生要尽快就医',
'抬肩痛不一定是肩周炎。外伤后突然不能抬臂、变形、严重肿胀、持续麻木或发热，需要尽快检查，不让人强拉复位。无这些信号可先减少反复举高手臂并温和活动；约两周不改善、加重或影响穿衣梳头，应复查。',
'**外伤后突然不能抬臂，或有突发剧痛、变形、严重肿胀、持续麻木、感觉丧失、异常冷/热、发热不适，尽快就医。** 不要自行复位或让人把肩“拽开”。[@0]\n\n肩袖是帮助肩关节稳定和抬臂的肌肉肌腱群。肩痛还可能来自关节、颈部等；肌腱问题与冻结肩的处理不同，不能凭抬手照片或年龄确诊。[@0]\n\n没有上述信号时，先减少反复高举和明显加重疼痛的任务，保留温和活动。两周左右还未开始改善、越来越痛或穿衣梳头困难，检查活动范围、力量和颈部线索，再决定影像、康复或其他治疗；片子正常也不能否定持续症状。[@0]',benefit='及早识别损伤，避免把所有肩痛都按肩周炎处理。')
add('neck-012','肩膀越痛越僵，检查冻结肩，别强拉硬扯',
'冻结肩常表现为夜里疼、活动越来越受限，自己抬手或别人辅助都困难。确诊后需兼顾止痛和活动恢复：疼痛阶段温和活动，随后按耐受进阶。不要完全不用肩，也别硬拉到剧痛；恢复虽可能以月计，持续加重仍需复评。',
'冻结肩又称粘连性关节囊炎，关节周围包膜等组织发炎、变紧，使活动范围缩小。夜痛、逐渐僵硬，自己和别人辅助活动都受限时值得检查，但不是所有抬肩痛都叫冻结肩。[@0][@1]\n\n治疗要同时改善疼痛与活动。严重疼痛时可讨论局部糖皮质激素注射，以帮助康复，并非一针永久解决。恢复可能以月计，进展慢不一定失败；完成一阶段仍受限或加重，应复评。[@0]\n\n**疼痛明显时用合适止痛措施、温和活动，不上重器械、不让家人硬扯；之后按康复计划恢复活动与力量。** 不完全停动，也不强行拉开。糖尿病、外伤或手术史主动说明，便于调整方案。[@0]',benefit='改善疼痛和活动能力，避免强拉或长期停用。')
add('neck-013','握东西时肘外侧痛，先减负，再练回力量',
'拧毛巾、提杯子或用工具时肘外侧疼，可能是网球肘，并不一定打过网球。减少最刺激的握持和拧转，保留轻活动，再逐步练力量。护腕或支带只能辅助；自护约两周仍痛、抓握变差或出现麻木无力，要检查原因。',
'网球肘常在握紧、提物或旋转前臂时引起肘外侧痛。问题涉及连接肌肉与骨头的肌腱，打字、手工、工具操作都可能诱发，不只是打网球。[@0][@1]\n\n支带、护腕或护肘可以暂时减轻部分人的不适，但戴着不痛不代表肌腱已恢复，也不支持立刻回到原高负荷。[@0]\n\n**减少最刺激的握持、拧转和提重任务，换握法、分段做，保留温和屈伸。** 症状允许后逐步练前臂与手腕力量。约两周仍痛、抓握越来越困难，或新发麻木无力，安排检查，分清肌腱、神经和关节问题。[@0]',benefit='降低重复刺激，逐步恢复抓握和工作能力。')
add('neck-014','手指夜里麻醒，检查腕管，再选夜间腕托',
'腕管综合征是手腕通道里的正中神经受压，不能只因常用电脑就自诊鼠标手。记录哪几根手指麻、有无抓握变差；适合保守治疗者可试保持手腕不过度弯折的夜间腕托。持续麻木、拇指无力或自护无效，需要复评。',
'腕管综合征是正中神经经过手腕通道时受挤压；颈部或其他位置的神经问题也能让手麻。记录哪几根手指、哪只手、是否夜里更重、甩手能否缓解，以及抓握是否变差，再去检查。[@0][@1]\n\n轻症可讨论保守处理，夜间腕托帮助保持手腕中立，即不过度弯折；止痛药只能短时止痛，没有充分依据证明能解除压迫。症状加重、拇指力量下降或自护无效，需复评，必要时做神经传导检查并讨论注射或手术。[@0]\n\n**获准先保守处理后，减少反复弯腕、握紧和震动工具任务，试合适夜间腕托。** 不要勒紧；戴后更麻、更痛就调整或停戴。约定复评时间，不无限换护具；孕期、糖尿病和正在用的药一并说明。[@0]')

add('hands-001','手部红热肿痛当天就医，伴全身异常走急诊',
'手背或手指明显痛、热、肿，红肿范围扩大，应当天检查，别只反复消毒。深部感染可能需要抗生素或引流；寒战、呼吸急促、眩晕、意识异常等要急诊。深肤色者发红可能不明显，糖尿病和免疫抑制情况也要主动说明。',
'**手部明显痛、热、肿，或红肿持续扩大，当天就医；伴寒战、呼吸急促、眩晕、意识异常或全身明显不适，直接急诊。** 发热、沿皮肤往上延伸的红线同样需要及时处理。[@0][@1]\n\n蜂窝织炎是累及较深皮肤的感染，入口可能只是小裂口；深肤色者发红未必明显。表面消毒不能替代深部感染治疗，是否需抗生素或脓肿引流由检查决定。[@0][@1]\n\n别用针挑脓。就诊说明何时开始、扩展多快、有无外伤和美甲操作，以及糖尿病、免疫相关疾病与用药。[@0][@1]',benefit='及时处理感染，避免误当普通敏感反复买护理品。')
add('hands-002','关键时刻用水皂洗手，免洗液不能替代所有清洁',
'如厕后、做饭和进食前、处理生食或伤口前后，用流动水和普通肥皂洗到手背、指缝与甲下，揉搓至少20秒。无水皂时可用至少60%酒精的手消毒剂，揉到干；明显脏油或化学污染仍需水洗，不靠烫水或抗菌香皂升级。',
'肥皂洗手能清除污物，酒精手消毒剂适合不便水洗的部分场景，不能包办明显脏油、化学污染或某些腹泻病原的清洁。日常也不必只为“抗菌”字样买更贵香皂。[@0][@1][@2]\n\n**如厕后、备餐进食前、处理生食后，以及处理伤口前后认真洗手。** 用清洁流动水湿手、普通肥皂起泡，揉搓手背、指缝和甲下至少20秒，冲净擦干。温水或凉水均可，不用烫水。[@0][@1]\n\n无水皂时，选标签至少60%酒精的手消毒剂，覆盖双手并揉至干，不马上擦掉。儿童需看护、防误食；洗后补护手霜。医疗、食品岗位另按工作流程。[@2][@1]',benefit='在易传播病原的关键时刻做好清洁，减少过度烫洗。')
add('hands-003','手干裂，洗后及时涂无香护手霜',
'手干裂时，把耐受的无香霜或软膏放在水池旁，洗后略湿就涂，觉得干再补。凡士林也可作简单选择，嫌黏可换霜；高价手膜和香氛不代表更修复。越涂越刺痛红痒先停，反复裂口、渗液要查湿疹等原因。',
'护手霜通过保水或减少水分散失缓解干燥；甘油、二甲硅油、矿物油、凡士林等可见于配方，但某个成分不能单独保证成品更好。明显干裂通常更适合霜或软膏，而非稀薄乳液。[@0]\n\n**洗手后轻拍干，在略湿时补涂；觉得干就再补。** 把无香、自己耐受的产品放在水池或随身位置，比只等睡前一次厚敷更容易坚持。凡士林油润，工作时嫌黏就换合适的霜，不必为手膜额外升级。[@0]\n\n越涂越刺痛、红痒，停可疑产品；保湿后仍反复痛痒、裂开或渗液，检查是否湿疹，不继续用厚敷遮住变化。[@0][@1]',benefit='缓解干燥和紧绷，把日常保湿做得容易坚持。')
add('hands-004','洗碗清洁戴合适手套，屏障霜不能挡化学品',
'反复沾水和接触清洁剂，先减少裸手接触，再按任务选手套。内侧保持干燥，棉内衬湿了要换；棉手套本身不防水，也没有一种材料挡住所有化学品。屏障霜只是辅助护理，不能当液体手套，已知橡胶或乳胶过敏需另选材料。',
'湿作业指反复沾水或接触洗涤剂等工作，会持续刺激皮肤。屏障霜可辅助护理，但职业防护指导不建议用它代替合适手套；棉手套只能吸汗，不能单独挡水或所有化学品。[@0][@1]\n\n**先减少裸手浸泡，能用带柄工具就用工具；手套按清洁剂或岗位化学品选择。** 不以厚度、“医用”或价格判断全部防护能力。岗位不准戴手套时，应调整工艺和防护，不靠一层霜代替。[@1]\n\n保持内侧清洁干燥，长时湿作业可用干燥棉内衬加合适防水外层，湿了就换，并安排安全摘脱透气。乳胶或橡胶相关过敏者避开相应材料；反复皮炎带产品、手套和接触史就诊。[@0][@2]',benefit='减少湿作业和化学刺激，避免误把护理当防护。')
add('hands-005','手反复红痒裂口，查湿疹与接触过敏',
'手反复红痒、脱屑、裂口或渗液，不一定只是干燥。记录洗涤剂、手套、消毒剂、戒指和美甲接触，减少刺激并到皮肤科确认。湿疹可能需处方抗炎，疑过敏可做斑贴试验；单手脱屑又有脚气或甲改变，还应排查真菌。',
'手湿疹是手部皮肤炎症，可有干裂、红痒、烧灼、小疱或渗液。水和清洁剂反复损伤可致刺激性皮炎；对某物质的免疫反应可致过敏性皮炎，两者能并存，单靠加护手霜未必够。[@0][@1]\n\n**记录接触物、发作时间和部位，拍照后到皮肤科判断。** 疑过敏可做斑贴试验：少量待测物贴皮肤，数天内按程序观察，不是擦一下没事就排除。单手脱屑、伴足癣或甲改变，可能需真菌检查。[@0]\n\n确诊湿疹后，减少诱因、保湿，发作期按部位和严重度用外用糖皮质激素等抗炎药。不因“激素”拒绝合理疗程，也不长期自行叠激素、抗真菌和抗生素混合膏。[@0]',benefit='找到持续炎症的原因，减少把湿疹、真菌和过敏混着试药。')
add('hands-006','手指小疱别挑破，单指成簇疼疱尽早就医',
'手掌或手指侧面反复痒小疱，可能是汗疱疹，但名字不代表汗堵住了，也不能据此买抗真菌药。温和清洁、保湿，反复发作再确诊。若主要一根手指明显疼痛、成簇起疱，尽早检查疱疹感染，别挑破或用患指碰眼睛。',
'汗疱疹又叫汗疱型湿疹，常在手掌、手指侧面反复起很痒的小疱；不能从名称判断是汗排不出，其他病也能起疱。另一类疱疹性瘭疽是疱疹病毒造成的手指感染，常为单指顶端疼肿、成簇小疱。[@0][@2]\n\n**反复痒疱先温和清洁、少抓挠、避刺激，洗后涂耐受的无香霜或软膏。** 确诊后再选短期外用抗炎、必要湿敷等，别挑疱排毒或长期用强药。[@0][@1]\n\n单指疼疱尽早就医，讨论是否需抗病毒；保持清洁覆盖，不挤破、不碰他人或自己眼睛，隐形眼镜可暂改框架。超过两天也不放弃求医，高热、加重或免疫功能受影响时主动说明。[@2]',benefit='分清相似水疱，减少抓破、传播和误用药。')
add('hands-007','指甲剪整齐、倒刺剪掉，别剪甲根薄皮',
'指甲剪到整齐、不勾挂即可，不要剪进皮肉。倒刺是翘起的小片皮肤，洗手后用清洁工具剪掉游离部分，别撕咬。贴着甲根的薄皮有保护作用，美甲也应保留；儿童或握不稳、看不清的老人，可请人协助。',
'倒刺是甲旁翘起的一小片皮肤；甲小皮则是贴着甲根、帮助封住皮肤与甲板之间入口的薄皮。后者不需要为“干净”反复推剪或用去死皮液清空。[@0][@2]\n\n**洗澡后甲较软时，用清洁指甲剪近直线剪，再轻磨尖锐边角。** 保留不勾挂、不过短的长度。甲下正常清洗即可，不用针刀刮挖；倒刺只剪游离部分，不连好皮撕下。[@0][@1]\n\n剪具先清洁，不用污染工具；商用共享器械另需相应灭菌流程。儿童按能力由成人协助，握力、视力或活动受限者也请人帮忙。剪后给甲旁指尖润肤，不靠咬甲整理。[@1][@2]',benefit='减少勾裂、倒刺与甲旁破口，保持易清洁的外观。')
add('hands-008','甲旁红肿停抠咬，有脓或加重及时检查',
'甲旁红肿痛可能是甲周炎，先停咬抠、剪甲小皮和美甲。轻微局限、无全身不适，可温水浸泡后擦干；有脓、加重或不改善就检查，别自行针挑。多指反复发作还可能与湿作业和皮炎有关，不能一直续抗生素。',
'甲周炎是指甲周围皮肤发炎，急性时会红肿疼痛、甚至积脓；反复多指发作也可能与湿作业、刺激或接触皮炎有关，不都是真菌或细菌感染。[@0][@2]\n\n**先停咬抠、剪甲小皮和美甲。** 轻微局限且无发热等全身症状，可温水浸泡辅助缓解，之后擦干，不整天泡着。[@0]\n\n有脓、越来越痛、肿胀扩大或自护无改善，检查是否需引流或用药。别自己针挑：成簇疼疱可能是[疱疹感染](#/entry/hands-006)，处理不同。反复多指发作带接触史、照片和药膏就诊，不一味续抗生素。[@0][@1][@2]',benefit='及时分清引流、抗感染或抗炎需要，避免反复试同一种药。')
add('hands-009','指甲黄厚先验真菌，再选涂药或口服药',
'黄、厚、脆不一定是灰指甲，外伤、湿疹和银屑病也可能相似。先检查，尤其口服药前必要时取甲屑确认；轻且局限可选药用甲搽剂，广泛或深部再讨论口服。旧甲恢复要等新甲长出，别为几天没变白就加量或购买包治激光。',
'灰指甲即甲真菌病，真菌感染甲板；外伤、甲银屑病等也可黄厚脆，外观不能确诊。检查受累范围，必要时取甲屑做显微镜或培养，尤其在口服药之前。[@0][@1]\n\n确认后，轻、局限且未深及甲根者可比较药用甲搽剂或溶液；多甲、广泛或较深者讨论口服和联合治疗。特比萘芬、伊曲康唑等需查肝功能、禁忌和并用药，不自行照网帖买长期疗程。[@0]\n\n**按复查与新甲生长判断，不因旧甲几天还黄就加量。** 受损甲替换需要时间。普通甲油不治疗；精油、草本液或激光的获益不能凭商家保证。工具分开，感染皮肤也同时处理。[@0]',benefit='让长期治疗针对已确认感染，减少不必要的药物和套餐。')
add('hands-010','指甲新长或变化的黑线，先看皮肤科',
'新长棕黑色带、不断变宽变深，或伴甲周变黑、裂甲、甲下结节，应到皮肤科检查。深线不等于癌，但不疼、曾碰伤也不能直接排除。可拍照记录变化，检查前保持裸甲；儿童有新色带或甲异常也应带去看。',
'甲下或甲周也能发生黑色素瘤，但不是每条深色线都恶性，网络照片不能确诊。**新出现或持续变化的棕黑色带，尽快安排皮肤科检查，不先用甲油、甲片遮住。**[@0]\n\n就诊说明出现时间、是否变宽变深、有无外伤，以及几枚甲受影响。甲旁变黑、甲板裂开或抬起、甲下小结节也需看；同角度照片可辅助比较，不能代替就诊或无限观察。[@0]\n\n检查前尽量保留裸甲。儿童新色带或甲异常也应带去检查；不要直接归为衰老、淤血或真菌。变化色带不等于都需急诊，伴急性感染或全身异常则按[感染警示](#/entry/hands-001)处理。[@1][@0]',benefit='及时确认需要检查的甲病变，避免遮盖后耽误。')
add('hands-011','做甲胶别让胶碰皮肤，手背也要防晒',
'甲胶靠灯光固化，耐久好看不等于养甲。操作时保留甲小皮，使用配套灯与胶，未固化胶别碰皮肤。手背可用广谱耐水SPF30以上防晒或合适露指手套；甲旁红痒、水疱、痛或甲分离先停做并检查，换个“无某成分”标签也不保证不过敏。',
'甲胶经灯光固化，从流动材料变成硬涂层，并非给甲补营养。未充分反应的甲基丙烯酸酯等可致敏；灯光还涉及紫外暴露，不能仅凭“LED”认定零风险。[@0][@1][@2]\n\n**操作前问清工具清洁，保留甲小皮，灯与胶按配套要求使用，未固化胶别碰皮肤。** 手背等暴露皮肤可用耐水广谱SPF30及以上防晒，或合适的不透明露指手套；不把防晒涂入未愈伤口。[@0][@1]\n\n甲旁红痒、肿痛、水疱或甲分离，停可疑美甲并到皮肤科确认，必要时斑贴检查。确诊过敏后告知牙科和其他医护，供选材参考；并非所有医疗材料都不能用，也不是去掉某一成分就不再过敏。[@2][@1]',benefit='保留妆效选择，减少可避免的皮肤接触与光暴露。')
add('hands-012','卸甲别硬撬，甲薄了先停打磨和补甲',
'甲胶翘起别硬撕、硬刮，先确认材料能否浸卸；硬胶未必能用同一方法。卸除剂只接触需要的部位，通风并远离明火，不买成分来源不清的快卸产品。甲变薄脆裂先停损伤操作、留短甲并保湿，疼痛或分离持续要检查。',
'浸卸剂是溶解某些甲胶的化学产品，不是所有甲胶、硬胶、甲片通用。反复撬、磨、补和卸可使天然甲变薄；某些含甲醛硬甲品频用也可能更脆或刺激，变硬不等于修复。[@0][@1][@2][@4]\n\nFDA在列明的2024–2025样品中检出二氯甲烷，部分标签不实；它不代表所有快卸胶或同品牌都含有，但说明成分来源不清不能忽略。[@3]\n\n**先确认材料和卸法，拿不准请熟悉材料的操作者处理，不硬撬。** 溶剂只接触需要部位，通风、避明火，不整手久泡。甲薄脆后减少打磨、美甲，保持短整齐并保湿；持续痛、分离或变色要检查。[@0][@1][@2][@4]',benefit='减少机械和化学损伤，避免用覆盖和硬化代替恢复。')
add('legs-001','腰痛伴排尿变化或会阴麻木，直接急诊',
'腰痛或腿放射痛时，新出现尿不出、大小便失控、会阴肛周麻木，或双腿明显无力，应直接急诊，不等表现凑齐。性功能或感觉新变化也要说明。重外伤后腰痛同样急诊；发热、寒战或疼痛快速加重需及时检查，别按普通闪腰按摩。',
'**腰痛或腿放射痛伴新发排尿困难、大小便控制改变、会阴肛周麻木，直接急诊。** 双腿明显无力麻木、快速恶化，或性功能/感觉新变化，同样立即评估。擦厕纸感觉变了、感觉不到膀胱是否满，也要说清，不等完全失禁。[@0][@1]\n\n会阴是生殖器和肛门之间的区域；马尾神经是腰椎下端控制腿、膀胱肠道及会阴感觉等的一束神经，受压可能需紧急处理，不能套用普通腰痛“不急着做MRI”的规则。[@1]\n\n重事故后腰痛走急诊；发热、寒战、明显全身不适、突发重痛或迅速恶化及时就医。肿瘤史、近期感染、无意消瘦和持续夜痛主动说明，不先正骨、强拉伸或按摩。[@0][@1]',benefit='尽早处理可能影响神经、膀胱或肠道功能的急症。')
add('legs-003','普通闪腰少量多次活动，别连续卧床等好',
'排除急症后的普通腰痛，可短时休息，但不必连续躺床或等完全无痛才活动。把走路、家务和工作分小段，暂减最刺激的搬抬，再随耐受增加。几周不改善、反复影响生活或越来越痛要复评；新发麻木无力、大小便变化则立即改走急症路径。',
'普通腰痛在排除急症、判断可保守处理后，恢复需要保留力所能及的活动；连续卧床并不是等疼痛过去的必需办法。骨折、术后或其他明确病因则按各自方案。[@0][@1]\n\n**短段走路、轻家务，暂减最痛的搬抬和重复动作，再逐步恢复。** 可短时休息，不需等完全不痛才做所有事情。冷热敷只作辅助，隔布并防温度损伤；感觉异常者别自行反复试温。适合自己的止痛药可帮助睡眠和活动，不代表服后即可冲回原负荷。[@0]\n\n几周无改善、反复影响工作睡眠或加重，复评与制定康复计划；新神经或大小便变化，按[急症入口](#/entry/legs-001)立即处理，不等原定复诊。[@0]',benefit='保持基本活动能力，逐步回到日常任务。')
add('legs-004','腰片写膨出退变，结合症状再决定检查治疗',
'膨出、退变是影像描述，也会出现在不痛的人身上，不等于病情严重或必须手术。普通腰痛先结合病史、力量和感觉检查，影像要看能否改变治疗。持续不改善或力量下降应复评；出现会阴麻木、排尿变化则急诊，不能拿旧片子排除新问题。',
'“膨出、退变”是影像描述，不是疼痛程度的刻度。系统综述发现，无症状成人也常有这些变化，随年龄增加；这既不证明你的痛是假的，也不说明所有膨出都无关。[@0]\n\n坐骨神经痛是沿神经通路向腿放射、可能伴麻木的痛。没有危险信号的腰痛或坐骨神经痛，通常先问病史、查神经并保守处理，不是起步必须MRI。[@1]\n\n**问清报告是否对应疼痛位置、腿部症状与查体，检查结果会如何改变治疗。** 持续不改善、力量下降或拟介入手术时再讨论影像；会阴麻木、排尿变化直接急诊。别为看退变是否消失反复拍片，也别凭旧片省掉新检查。[@1][@2]',benefit='减少无目标重复检查，保留真正需要影像的治疗入口。')
add('legs-005','慢性腰痛练回日常能力，别只续护腰牵引疗程',
'腰痛超过三个月，要先确认有无特定病因。慢性原发性腰痛以活动、力量和自我管理为核心，护腰、腰带、牵引不宜作常规主治疗。按摩可辅助，但应看走路、坐立、睡眠和工作是否改善；骨折术后已安排的支具不能自行停。',
'慢性原发性腰痛指持续超过三个月、经评估没有其他明确疾病解释的腰痛。身体、心理和社会因素都可能影响疼痛，不等于“都是想出来的”。[@0]\n\nWHO不建议对多数这类成人常规使用护腰、腰带或牵引；按摩和部分手法可作辅助，但不替代主动活动。骨折、术后等有明确支具需要，是另一种情境。[@0]\n\n**和康复人员定逐步活动、力量与自我管理计划，必要时结合疼痛应对支持。** 用走多久、坐多久、睡眠和工作能力复评；只当下放松、必须不断续费才能维持时，重评方案，不仅追加被动疗程。不要自行停骨折、术后已安排的支具。[@0]',benefit='把护理投入用于持续的功能恢复。')
add('legs-002','一侧腿突然肿痛尽快查血栓，胸痛气短拨120',
'一条腿新肿痛、颜色变化，尤其近期手术、住院、久坐长途后，要尽快排查深静脉血栓，别先强揉或打筋膜枪。症状不必齐全，年轻也不能直接排除；伴胸痛或气短立即拨120，不自行开车，也不自行吃阿司匹林试治。',
'**单侧腿新肿、痛，伴颜色或静脉变化，尽快到医院检查；同时胸痛或气短，立即拨120，不自己开车。** 不需等所有表现齐全。[@0]\n\n深静脉血栓是深部静脉里的凝血块，脱落进入肺部可能形成肺栓塞。手术、住院、长期不动、长途旅行、既往血栓、雌激素相关药物及孕产期会影响风险，但不能凭年轻或按压测试排除。[@0]\n\n未排除前，不强揉、打筋膜枪或套紧袜拖着观察。就诊说明诱因和用药，由超声等检查确认后再安排抗凝方案；不自行吃阿司匹林或购买抗凝药作通用预防、试治。[@0]',benefit='减少把血栓误当肌肉疲劳的延误。')
add('legs-006','髋膝痛先看能否负重，红热肿别拖着练',
'跌倒后严重髋痛、不能负重或感觉下降，直接急诊。髋部新发肿热、突然剧痛，即使不发热、没摔也应当天检查；膝明显肿、变形、锁住或打软腿也需评估。轻症先减刺激并保留舒适活动，持续不改善再查原因，不凭弹响判断关节磨坏。',
'**跌倒后严重髋痛、不能负重或感觉下降，直接急诊。** 髋部新肿、发烫，即使无全身发热；或没摔却突然严重髋痛，都应当天评估。[@0]\n\n膝明显肿、变形、锁住、打软腿，或红热伴发热，不靠膏药硬撑训练。无痛的偶尔弹响常见，不能据此说软骨磨坏；疼痛弹响和功能改变则需要检查。[@1]\n\n**轻症先减长站、跑跳等最刺激任务，保留舒适活动。** 髋痛两周无改善、反复影响生活或晨僵较久，膝痛数周未改善，安排就诊。年轻人的肌腱、负荷问题不直接套老年骨关节炎产品；儿童髋痛另有评估路径。[@0][@1]',benefit='把急需检查的关节问题与可先调负荷的疼痛分开。')
add('legs-007','髋膝骨关节炎要适量练，别只为省关节停动',
'确诊髋膝骨关节炎后，适配的力量和有氧活动是核心方案，年龄大也不等于只能静养。从能完成的动作和分量开始；持续加重、肿胀或活动能力下降就调负荷并复评。超重者可讨论稳妥减重，正常体重不盲减；治疗后仍明显影响生活再看专科。',
'骨关节炎涉及软骨及关节其他组织改变，不是“关节已经报废”。确诊后，肌力与整体耐力训练是核心治疗；年龄大、怕磨损都不是长期停动的理由。[@0][@1]\n\n**从现有能力选站坐、步行、骑车或水中活动，配局部力量训练，逐步增加。** 初期不适不一定失败，但持续明显加重、肿胀或活动下降，应减负、查动作和诊断，不强撑锐痛。超重时将饮食与活动结合讨论减重，正常体重不为护膝盲减。[@0][@1]\n\n合适止痛和辅助工具用于帮助活动。规范非手术方案后仍明显影响生活，再讨论专科治疗或关节置换，不只无限换保健品。[@0]',benefit='改善疼痛与日常活动能力。')
add('legs-008','护膝鞋垫按病因和尺寸选，不是越紧越好',
'护膝、鞋垫有不同用途，不是健康人预防磨损、矫正腿型的通用品。已确诊膝骨关节炎，可按受累部位比较支具，楔形鞋垫不应凭宣传默认买。看是否走得更舒服；戴后更痛、发麻、压皮肤要调整，不靠勒紧继续忍。',
'护膝可提供特定支撑，鞋垫可改变部分受力，但不同材料、结构与用途不能混为一类。2026 ACR对膝骨关节炎的胫股和髌股支具作条件推荐，分别对应主要承重关节和髌骨接触部位，不等于所有弹力护套有效。[@0]\n\n同一推荐对膝/髋骨关节炎的内外侧楔形鞋垫为条件性不推荐；“改变受力”原理不能直接推出疼痛或活动获益。[@0][@1]\n\n**先说清需解决的是不稳定、哪处痛或哪项活动，再核尺寸与用法。** 看真实行走和疼痛变化，戴后更痛、麻或压皮肤就调整。没有明确需要不必一套买齐；辅助品不替代训练，外伤或术后已指定支具仍按原方案。',benefit='让辅助用品服务具体活动，而不是为防磨损盲买。')
add('legs-009','氨糖不能承诺补回软骨，关节痛先做正规管理',
'氨糖和软骨素虽是关节相关成分，口服并不等于修复磨损。髋膝骨关节炎的现行主要推荐不把它们作常规核心治疗，健康人也不能借患者研究推预防。优先运动、合适止痛与功能复评；服华法林、孕哺或已有处方者先确认相互作用。',
'氨糖是氨基葡萄糖，软骨素也是软骨组成成分，但吃进去不等于补回软骨。对髋膝骨关节炎，2026 ACR摘要强烈不推荐把氨糖、软骨素或组合当常规治疗。[@0]\n\n研究与制剂评估曾不一致，不能说所有人绝对零效；但缓痛、走路改善和修复结构是不同结局，目前不能承诺逆转磨损，更不能由患者研究推出健康人预防关节病。[@1]\n\n**把训练与功能复评做好，需止痛再选有适应证的药。** 膝骨关节炎可评估局部非甾体抗炎药；不能直接推给髋部深关节。胃溃疡、肾病、心血管问题、孕哺或抗凝用药需先确认安全，不自行叠同类口服药。[@0][@2][@3]',benefit='减少为“补软骨”承诺付费，优先改善症状与功能。')
add('legs-010','跑步逐步加量，关节肿痛时减负检查',
'跑步不等于必然磨坏膝盖，现有研究也不能保证任何跑量终身安全。新手或返跑先走跑交替、留恢复日，不同时猛加速度和距离。锐痛、越跑越痛、持续肿胀或明显痛超过48小时，要减量评估；不靠贵鞋保证不受伤。',
'成人研究综述在纳入随访中，未发现跑步普遍让膝骨关节炎影像或症状变差；多数并非随机试验，不能据此保证无限跑量安全或一定预防关节炎。[@0]\n\n**新手与返跑者从当前耐受起步，走跑交替、跑步日之间留恢复，不同时猛加距离和速度。** 伤后能否起跑还看病种、力量与日常功能，不为怕磨损永久停跑，也不跟网红挑战跳级。[@1]\n\n轻微肌肉酸痛不同于锐痛、持续关节肿或越跑越痛。出现后者，或明显痛超过48小时，减训练并评估；停跑约一周仍膝痛、严重或肿胀时更早检查。鞋先合脚，贵型号不能保证防伤。[@1][@2]',benefit='保持运动机会，同时避免带伤硬冲。')
add('legs-011','扭伤先保护减负，变形或不能负重要检查',
'扭伤后先停诱发运动，保护、抬高并适当隔布冷敷，别立刻热泡、推拿或敲筋膜枪。变形、麻木、发冷发蓝走急诊；剧痛、肿胀扩大或不能负重走几步要及时检查。确认可自护后逐步恢复，返场看力量和稳定，不只看疼痛轻了没有。',
'**伤后明显变形、麻木、发冷或发蓝，直接急诊；剧痛、越来越痛、肿胀淤青扩大或不能负重走几步，及时检查。** 还能勉强走，不足以排除骨折等损伤。[@0]\n\n扭伤主要伤到连接骨与骨的韧带，拉伤涉及肌肉等组织。起步是停诱发运动、保护减负、抬高；初期可隔布冷敷，每次不超过20分钟，最初几天避免热泡、热敷和按摩，绷带不勒到麻或变色。[@0]\n\n确认能自护后，随耐受恢复温和活动，不长期完全不动。反复打软腿、恢复迟缓或功能不回，做康复评估；回跑跳看力量、稳定与任务需求，不凭固定天数或止痛效果。[@0]',benefit='识别严重损伤，减少早期刺激并按功能恢复。')
add('legs-012','腿胀青筋先查原因，压力袜按供血和尺寸选',
'久站后腿沉、酸胀或静脉凸起，可先规律走动、间歇抬腿，再检查原因。压力袜能缓解部分症状，却不永久修复静脉；动脉供血不好者可能不适合。穿后冷、麻、变色或疼要脱下求助；单侧新肿痛排查血栓，静脉出血或破口不愈及时看病。',
'静脉曲张是皮下静脉扩张迂曲，可伴久站腿沉、酸胀或踝肿。压力袜用外部压力帮助回流，不能永久修复静脉；动脉供血问题者可能不适合，普通瘦腿袜也不是同一用途。[@0][@2]\n\n**规律走动，久坐久站间隙起身，休息适当抬腿。** 需压力袜时，按专业测量的尺寸、压力等级和用途选，不买最紧款；穿平整、不卷边，新冷、麻、蓝紫或痛时脱下并及时求助，夜间是否脱按具体方案。[@0][@2]\n\n单侧新肿痛先按[血栓路径](#/entry/legs-002)检查。静脉痛痒肿、皮肤变化或伤口不愈需评估，必要时超声、讨论消融或硬化；静脉出血当天求医，量多、止不住或头晕虚弱立即急诊。[@0][@1]',benefit='让压力治疗适配供血和实际症状，避免把急性肿痛当疲劳。')

add('feet-001','糖尿病足新破皮或红热，立即联系医院',
'糖尿病、足部感觉下降或循环不良时，不痛不代表伤口安全。新破皮、水疱、红热肿或渗液，立即联系医疗团队，不等复诊。突发冷麻、明显变色或感染伴全身不适走急诊；日常看脚底趾缝，别泡脚、削茧或自行贴鸡眼膏。',
'**糖尿病或高风险足出现新破皮、水疱、红热肿、流液，立即联系糖尿病足团队或医院。** 神经损伤可让伤口不疼，供血不良又会妨碍愈合，不能等痛了再说。[@0][@1]\n\n突发冷、麻、苍白、蓝黑或剧痛，或感染伴全身明显不适，尽快急诊。坏疽是缺血或感染等造成组织坏死，不适合等颜色自己恢复；没有糖尿病也要重视这些变化。[@1][@2]\n\n**每天检查脚面、底、跟和趾缝，看不清用镜子或请人帮忙。** 温水洗后擦干，足背足底保湿、趾缝不厚涂，不泡脚；穿鞋前查石子、内衬破损，定期查感觉和血流。不自行加热、磨削或贴腐蚀性鸡眼药。[@0][@1]',benefit='在疼痛警报可能失灵时，及早处理伤口和感染。')
add('feet-002','趾缝白软脱皮先擦干，反复发作再查病因',
'趾缝发白、脱皮可能是潮湿泡软，也可能是脚气或皮炎，不能凭白或痒就确诊。先轻洗擦干、换湿袜晾鞋，不撕皮。反复、表现不典型或治疗无效时，检查趾缝、足底和甲，必要时验真菌；红热肿痛尤其合并糖尿病要及时看病。',
'足癣就是俗称脚气的真菌感染，可有趾缝痒脱屑或足底足侧脱皮；但潮湿刺激、鞋材过敏、湿疹和银屑病也可能相似。“白”“痒”以及单脚或双脚发作，都不能单独确诊。[@0][@1]\n\n**先改潮湿：洗后轻按干趾缝，换湿袜，让鞋干透，不撕软皮。** 反复、皮疹不典型，或完成治疗仍无效时，到皮肤科检查趾缝、足底与甲；必要时刮皮屑镜检、部分加培养，并非每个典型病例都必需检测。[@0]\n\n已红、热、肿、明显疼痛或裂口感染，尤其糖尿病、免疫抑制者，及时评估，不再只试清洁和止痒用品。[@1]',benefit='避免把皮炎当脚气反复用错药。')
add('feet-003','脚气按说明完成抗真菌疗程，别单用激素止痒',
'确诊局限脚气后，通常先用适合部位的外用抗真菌药，按具体成分和制剂完成疗程，别刚不痒就停。“除菌祛味”不等于能治真菌。未确诊别单抹激素或自行配强激素；规范治疗仍无效，应复查病因和用法，再决定是否升级。',
'抗真菌药用于真菌感染；特比萘芬、克霉唑等是局限足癣常见外用选择。“抗菌”“祛味”广告不代表含治疗真菌的有效成分。乳膏、喷剂、粉剂按部位、年龄与具体国内说明书选，不按价格分强弱。[@0][@1]\n\n疗程因成分、剂型而异：多数需数周，也有更短制剂，不能统一规定天数。激素可能压住外观却让真菌扩散；医生对少数重炎症病例短期合用，不等于可以自己选复方。[@0][@2]\n\n**按完整疗程使用，痒先退也不自行提前停。** 未确诊不单用激素或自行混强激素；疗程后无效、范围扩大或多处感染，复查诊断和用法，必要时讨论处方口服药。[@0][@2]',benefit='控制真菌感染，减少误用激素和提前停药造成的反复。')
add('feet-004','洗后擦干趾缝，湿袜及时换，公共浴室穿拖鞋',
'减少潮湿和共享物品，比把脚洗得更狠更重要。洗澡、游泳、运动后擦干趾缝，换湿袜，鞋干透再穿；公共淋浴、更衣室穿自己的拖鞋，不共用毛巾鞋袜。已患脚气还需治疗，预防习惯不能替代药物，也不需要健康人常年涂药。',
'足癣可经接触传播，长期闷湿也不利于管理；护理重点是保持干燥、减少共享接触，不是烫洗或天天消毒。鞋袜看实际透气、吸湿、干燥和适配，无唯一必选纤维。[@0][@1]\n\n**洗澡、游泳或运动后擦干脚和趾缝，湿袜及时换，轮换鞋，干透再穿。** 公共淋浴、更衣室穿自己的拖鞋，不共用毛巾、鞋袜；足部毛巾单用并清洗。[@0]\n\n治疗结束继续这些习惯。频繁复发、合并灰指甲或家人类似症状，查感染来源和未处理部位；不能靠清洁代替已确诊足癣治疗，也不给健康人常年抗真菌药。[@0][@2]',benefit='减少潮湿和共享接触带来的感染、复发机会。')
add('feet-005','脚臭先干燥鞋袜，汗多再选足用止汗剂',
'脚臭常和汗、细菌有关，有脱皮痒裂口时再查是否脚气，不能凭味道确诊。先洗净擦干、换袜晾鞋；总被汗浸湿，可试适合足部的止汗剂，香味除臭只针对气味。自护无效、突然多汗或夜汗、影响生活，应检查原因。',
'止汗剂减少出汗，除臭剂主要减少或遮掩气味；脚臭不等于脚气，汗和细菌也会形成气味。伴脱皮、痒或裂口时再按皮肤表现查病因。[@0][@1]\n\n**先清洗擦干、换湿袜、轮换晾鞋；脚总湿透，再选明确适用于足部的止汗剂。** 按说明在干燥皮肤使用，部分安排睡前；刺痛或皮炎就停或调整，不越刺激涂越多。[@1]\n\n自护无效、影响工作社交，不热不动也大汗、夜汗或与新药有关时求医。必要时讨论更强外用或离子导入——用水或湿垫传递弱电流减汗的治疗，不是在家随意接电。[@2]',benefit='分别处理汗湿和气味，减少只靠香味反复遮盖。')
add('feet-006','足跟干裂先保湿，深裂出血别用酸类磨皮',
'普通干硬浅裂可先温和清洗、洗后保湿，配合合脚包跟鞋，睡前凡士林也是选择。足用尿素霜可软化厚角质，但高浓度不适合所有裂口；有伤口、渗液或炎症先不用酸类足膜。深裂出血、红热痛或反复不好要检查，高风险足更应早处理。',
'保湿减少干燥，尿素等足霜可软化厚角质；AAD列10%–25%尿素或酸类选项，不代表深裂、渗液或所有脚都能用，更不能当裂口消毒剂。[@0][@1]\n\n**没有糖尿病、感觉或循环异常的普通浅裂，先少热水久泡、温和无香清洗，洗后及时涂霜。** 睡前可凡士林配干净袜，鞋合脚、有足跟支撑，少长期露跟或穿磨损鞋。厚角质可试合适足霜，刺激就停；趾缝保持干燥，不一并糊厚霜。[@0][@2]\n\n伤口或炎症先不用酸类足膜。深裂、出血、红热肿痛或保湿仍不好，要查原因；糖尿病足新裂口及时求助，不先连续泡脚磨皮。[@1][@2]',benefit='改善浅表干裂，避免去角质进一步损伤裂口。')
add('feet-007','鞋磨出水疱先停摩擦，清洁覆盖别挑破',
'磨出水疱先换鞋、减少摩擦，再轻洗拍干、柔软覆盖，不要挑破或撕疱皮。水胶体可保护适合自护的普通摩擦疱，却不是所有疱和感染的一贴通用方案。脓液、红热扩展、越来越痛需就医；糖尿病新水疱应立即联系医疗团队。',
'摩擦水疱是皮肤反复摩擦后的起疱；水胶体是保留适度湿润的敷料，可保护适合自护的普通摩擦疱、减痛，不包治感染或其他原因的水疱。[@0]\n\n**先换掉磨脚鞋，减摩擦，再轻洗、拍干、柔软贴或衬垫覆盖。** 不针挑、不撕皮。已破先洗手，让液体排出后覆盖，不反复挤；很大很痛时可由专业人员无菌处理。[@0]\n\n黄绿脓、明显热、红肿扩展、越来越痛或反复不明起疱，应就医，别一层层贴着走。糖尿病新水疱立即联系团队。新鞋短时逐步适应，运动后换湿袜；烫伤、过敏、多发不明疱另按病因处理。[@0][@1]',benefit='减少继续摩擦和人为破皮带来的疼痛与感染。')
add('feet-008','鸡眼厚茧先换鞋减压，不自行拿刀削',
'鸡眼、足茧常与同一处受压摩擦有关，只削薄却不换鞋容易复发。先选宽松合脚鞋和合适软垫，低风险成人才轻柔处理完整硬皮。糖尿病、循环不良、免疫抑制或老年人先看专业人员；脱皮足膜只改部分粗糙外观，不治疗脚气。',
'鸡眼是较小的局部硬皮，足茧通常范围更大，常由持续压力和摩擦引起。脱皮足膜靠酸类脱表层角质，不能改变受力或治疗真菌。[@0][@2]\n\n**先换宽鞋头、合脚、低跟且不磨患处的鞋，试软垫或鞋垫减压。** 无高风险因素成人，可轻用浮石或脚锉处理完整硬皮并保湿，不拿刀削、剪、挖。[@0]\n\n糖尿病、循环不良、免疫低下或老年人，先让医生或足部人员判断，不自行用鸡眼药和去茧。出血流脓、影响走路或三周自护无改善要检查。湿疹、银屑病、皮炎、脚气、红疹或伤口不先用足膜；使用后不叠磨脚、撕皮。[@0][@1][@2]',benefit='减少持续压力，避免美容去角质损伤高风险足。')
add('feet-012','足底硬疙瘩先分病因，确诊跖疣再选治疗',
'脚底硬疙瘩可能是跖疣，也可能是受压形成的鸡眼，黑点和疼痛都不能单独确诊。先别针挑刀挖；确诊后不痛、不影响活动可讨论观察，需治疗再比较水杨酸或门诊冷冻。糖尿病、感觉或循环异常、免疫抑制者不要自行用酸和冻疣。',
'跖疣是足底的病毒性疣，硬皮下有时可见黑点；鸡眼更多与压力摩擦有关。黑点、疼痛或挤压反应都不能代替诊断；不确定、出血或明显变化，先看皮肤科。[@0]\n\n疣可能自行消退，但可能很久；不痛、不妨碍活动可讨论观察。水杨酸疣制剂逐步去掉病变表层，门诊液氮冷冻常需多次，家用冻疣并不等同门诊治疗。[@0][@1]\n\n**确诊后按症状和风险选观察或治疗，药只用目标部位，痛、破损或明显刺激就停并复评。** 糖尿病、感觉循环异常或免疫抑制先就医；不抠抓、不共用磨具，泳池覆盖病灶、公共地面不赤脚。[@0][@1]',benefit='避免把疣当鸡眼挖除，选择与症状相称的处理。')
add('feet-013','起床第一步足跟痛，先减负、换支撑鞋',
'起床或久坐后第一步足跟痛，走开稍好、久站又痛，可能与足底筋膜有关，但不能凭症状自诊。先减突增的跑跳久站，穿有缓冲支撑的鞋，温和拉伸足底和小腿。两周不好或影响走路要复评，麻木、感觉下降或糖尿病伴足痛更早检查。',
'足底筋膜是连接足跟与前脚掌的支撑组织。起床或久坐后第一步更痛、走开稍好、久站跑走又重，是常见线索，但足跟痛也有其他原因。[@0]\n\n**无急性损伤等异常时，减少突增的跑跳久站，避免赤脚走硬地，换足跟缓冲和足弓支撑合适的鞋。** 可比较鞋垫、足跟垫是否减痛，温和拉伸足底和小腿，暂换较少冲击的活动，不硬踩痛点或拉到剧痛。[@0]\n\n两周自护无改善、反复加重或影响日常，评估病因和康复；麻木、感觉下降、糖尿病足痛更早查。保守措施无效再讨论夜间支具、注射或冲击波，不以贵鞋垫作为治疗门槛。[@0]',benefit='减轻反复刺激，恢复耐受的行走与活动。')
add('feet-014','拇外翻先穿宽鞋，矫正器不能承诺掰直骨头',
'大脚趾偏向其他脚趾、根部凸起时，先看疼不疼、是否影响穿鞋走路。宽鞋、软垫和部分鞋垫可减摩擦或疼痛，却不能保证永久矫正骨性结构。没症状未必需治疗；换鞋后仍痛、活动受限，再讨论手术和恢复安排。',
'拇外翻是大脚趾向其他趾偏、根部关节区凸起的形态变化。凸起大不一定更痛，没有疼痛和活动问题也不一定需治疗。[@0]\n\n软垫、硅胶套或分趾用品可比较减摩擦；鞋垫可能减轻部分疼痛，证据有限，也不会矫正既有结构。短时舒服不能证明戴几周就能永久“掰直”。[@0]\n\n**先换前部够宽、合脚的鞋，少尖头、高跟和挤压。** 按穿鞋行走的实际改善决定辅助品是否留用。调整后仍痛、影响活动，再评估手术；问清检查、恢复期、风险和功能目标，不按广告照片买套餐。[@0]',benefit='按疼痛和功能选择处理，减少无效矫形承诺。')
add('feet-009','嵌甲疼了别往肉里挖，反复化脓要就医',
'趾甲边缘扎肉后，越挖两角越容易受伤。红肿痛时停挖剪、换宽鞋、清洁干燥；日常平剪，不剪太短或深弧角。流脓、发热、自护无效或有糖尿病时及时检查；严重反复者可讨论专业甲缘处理，不是每次都必须拔整片甲。',
'嵌甲是趾甲边缘长入或压入旁边皮肤，常见于大脚趾。反复挖甲角会继续损伤；抗菌药也不能消除甲缘持续刺肉的机械原因。[@0]\n\n**红肿痛时停用小剪刀深挖，也别让修脚反复掏，换宽鞋，清洁干燥，让甲缘长出。** 平时平剪、不过短，不把两角剪成深弧。[@0]\n\n流脓、发热寒战或自护无改善，检查感染和甲形；糖尿病一出现嵌甲就及时求医。抗生素只在适当感染情境使用。严重、反复者可评估局麻下部分甲缘或整甲处理，问清范围、复发和恢复；高风险足不自行泡脚修剪。[@0]',benefit='减少挖剪伤口，并及时处理持续的机械刺激。')
add('feet-010','趾甲黄厚先确认真菌，别先买长期根治疗程',
'黄厚碎裂不一定是灰指甲，先确认病因再选几个月的治疗。少量早期可讨论甲用外药，广泛、多甲或到甲根时评估口服及风险；无痛、并发症风险低也可讨论观察。旧甲恢复要等新甲长出，激光、草本或拔甲不保证根治。',
'甲真菌病即灰指甲；外伤、银屑病等也会改变趾甲。医生可取甲屑镜检或培养，初次阴性但仍高度怀疑时可能重新取样，不能照商家照片定病。[@0][@1]\n\n少量、早期、未及甲根可讨论阿莫罗芬等甲用外药；广泛、多甲时，确认后评估口服特比萘芬等。药物要看真菌类型、肝病、并用药和监测需要；无痛且并发症风险低、能接受外观者也可讨论观察。[@1]\n\n**按复查和新甲生长判断，不要求旧甲立刻变好。** 修薄可辅助，剪掉拔掉不等于杀真菌；激光单独治疗证据不足，草本偏方不作根治承诺。年龄、孕哺和多药情况分别告知，不自行按外国剂量吃药。[@0][@1]',benefit='在药物风险、外观和症状之间做合适的治疗选择。')
add('feet-011','趾甲新黑线或越变越宽，先检查别遮盖',
'趾甲新出现棕黑纵线，尤其变宽、形状不规则、甲旁变黑，或有甲裂、甲下结节，应安排皮肤科检查。它不等于一定是癌，也不能只当淤血、真菌或缺营养。记录出现时间、外伤和变化，留清晰照片，不用美甲遮住后长期等。',
'甲下黑色素瘤虽少见，也会发生在趾甲下或周围；新黑线、持续变宽、形状不规则、甲旁变黑、甲裂抬起或甲下结节，是需评估的线索。不是每条黑线都恶性，也不能凭一张照片排除。[@0]\n\n**安排皮肤科检查，说明何时出现、有无外伤、怎样变化。** 可以保留清晰照片回顾，但不要反复涂抗真菌药或美甲遮盖后拖延。进一步甲部检查、是否取样，由医生判断；年轻并不能自动排除。[@0]',benefit='及时确认甲部色素变化，不让遮盖或经验用药拖延。')

add('bodyskin-001','伤口压不住血、很深或感染加重，及时就医',
'持续加压仍止不住血、伤口很深、嵌异物或感觉活动异常，直接急诊，不自己掏玻璃。仍有泥土、咬伤或红肿疼痛流脓增加，应当天检查。皮肤痛热肿伴寒战、呼吸变快、眩晕或意识异常，同样急诊，别继续等消毒和药膏见效。',
'**加压仍止不住血、深伤、嵌玻璃等异物，或感觉活动异常，直接急诊，不自己掏深处异物。** 伤口仍脏、人或动物咬伤、红肿痛脓增加，当天检查，并评估破伤风等预防。[@0]\n\n明显痛、热、肿可能是较深皮肤感染，即蜂窝织炎；深肤色者发红未必明显。伴寒战、快呼吸、眩晕、意识异常或全身明显不适，立即急诊。[@1]\n\n就诊说明伤口来源、变化和处理经过，以及糖尿病、免疫抑制、近期手术等情况。消毒液和祛疤膏不能代替深部感染治疗。[@0][@1]',benefit='及时处理出血、深伤和感染，避免当作正常结痂拖延。')
add('bodyskin-002','洗后干痒就降水温、缩短洗浴，别搓到发红',
'洗澡后紧绷、痒或掉屑，先把烫水换温水，缩短泡洗，停搓红皮肤的工具。干燥皮肤可从约5至10分钟短浴试起，轻拍干后保湿；这是护理起点，不是精确禁令。搓澡巾、磨砂、酸类无需一起用，持续起疹应查病因。',
'洗后紧绷干痒说明这套清洁可能不适合当前皮肤，并非更用力才洗干净。AAD对干燥皮肤建议约5至10分钟温水洗浴，清洁剂用于需去污部位，轻拍干；时长是起步参考，不是过一分钟就有害。[@0]\n\n**先降水温、缩短长泡洗，停会搓红皮肤的工具，洗后保湿。** 不叠磨砂、酸类沐浴露和搓澡巾。粗糙若是毛周角化，硬搓会刺激；背部痘也不宜反复刷洗。减少刺激仍起疹，再检查具体病因。[@1][@2]',benefit='减少清洁造成的紧绷、干燥和抓挠。')
add('bodyskin-003','身体干燥起屑，洗后微湿时涂无香润肤霜',
'干燥起屑时，洗后微湿就涂无香霜或软膏，觉得干再补。很干部位可用较厚霜或凡士林，价格、香味和清爽感都不直接等于保湿力。若洗浴保湿已调整仍红痒、裂口或涂什么都灼痛，应查湿疹等原因，别只不停换品牌。',
'润肤品靠保水或减少水分流失改善干燥。甘油等可保水，凡士林、矿物油、聚二甲基硅氧烷等可减少散失；“身体乳”只是剂型称呼，不由香味和价格决定效果。很干时厚霜或软膏通常比稀乳液合适。[@0]\n\n**选无香精、耐受且愿意持续用的产品，洗后微湿就涂。** 不为一个热门成分更换整套用品。洗浴和保湿已调整仍持续红痒、开裂或每次灼痛，检查湿疹等病因，不把所有皮疹当缺水。[@0]',benefit='缓解干燥紧绷和脱屑，不承诺治疗所有皮肤病。')
add('bodyskin-004','胸背痘按痤疮治，深痛结节或留疤早点就医',
'胸背黑白头和红痘可能是痤疮，强搓去油不能替代治疗。轻症可了解过氧化苯甲酰等正规药物，按具体剂型说明使用，留意刺激和漂白衣物。深痛结节、开始留疤直接看皮肤科；规范处理6至8周无改善再查方案。',
'痤疮发生在毛囊皮脂腺，胸背同时有黑白头和红痘是线索；硫磺皂、强去油或搓背不能替代针对痤疮的药。过氧化苯甲酰是常用药，可减少相关细菌，普通去角质或沐浴用品并不自动有同等效果。[@0]\n\n**轻度少量痘，按正规产品说明选择合适药物和剂型，先小范围观察耐受。** 洗剂与留敷凝胶用法不同，不搬国外某浓度停留时间；干燥刺激就调整，注意漂白衣物。运动后换汗衣、减背包摩擦，不抠挤。[@0]\n\n深痛结节或已经留疤直接皮肤科；规范处理约6至8周无变化也需复查。孕哺、儿童、过敏史先核药物，不自行加维A酸类。[@0]',benefit='让轻症有针对性的起步治疗，并在结节留疤时及时升级。')
add('bodyskin-005','剃毛或泡池后起小疹，先停刺激，别混涂药',
'剃毛、闷汗、紧身摩擦或泡温泉后突然起一批小疹，可能是毛囊相关问题。先停剃拔和摩擦，换干净宽松衣，不挤脓疱；出池脱湿泳衣、淋浴并洗衣。不同病因外观相似，反复、扩大或更痛要先检查，不自己叠抗菌、抗真菌和激素药。',
'毛囊是毛发生长的小结构，发炎或感染也会像长痘；外观不能分清全部病因。泡温泉、热水池后的毛囊炎可能与铜绿假单胞菌有关，泳衣覆盖处常较明显，不能直接判断为真菌。[@0][@1]\n\n**先停剃拔、减少闷汗与摩擦，不挤脓疱，也别照痤疮路线叠刷酸。** 出池即脱湿泳衣，用清洁剂淋浴并清洗泳衣。小范围轻症去诱因后可能缓解，池后轻疹常数天改善。[@0][@1]\n\n反复、扩大、更痛或恶化需确认诊断，必要时查感染来源，不为预防长期涂抗生素。发热、迅速扩大痛热肿或免疫抑制，按[感染警示](#/entry/bodyskin-001)处理。[@0][@1]',benefit='减少重复刺激和无目的叠药，及时识别需治疗的感染。')
add('bodyskin-006','鸡皮肤先保湿，在意粗糙再试一种角质护理',
'上臂大腿稳定的小粗疙瘩若是毛周角化，不是没洗净，无不适可以不治。想改善触感，先保湿，再按说明少量试一种尿素或乳酸类产品，不叠多种酸、不硬搓。刺痛红脱皮就停；疼痛、脓或诊断拿不准，应重新检查。',
'毛周角化俗称鸡皮肤，是毛囊口角质堆积，不是污垢，也不需要逐个挤出东西。确诊、稳定且无不适时可以不治疗，护理也不能保证永久消失。[@0]\n\n**想改善粗糙，先保湿，再按标签少量试一种含尿素或乳酸的身体霜。** 它们可软化调理角质，但单看成分不能保证成品效果。不叠多种酸，不硬搓、抠挤或刺激性脱毛。[@0]\n\n刺痛、红斑、脱皮就停几天；疼、化脓或一直不确定病名，重新检查，不把所有疙瘩叫鸡皮肤。儿童、孕哺、大面积及破皮护理另核产品限制。[@0]',benefit='按个人意愿改善粗糙，不强迫治疗外观差异。')
add('bodyskin-007','闷汗小疹先降温，褶皱红烂要查感染和皮炎',
'热天刺痒小疹先降温、穿宽松衣、避免抓挠；腋下或大腿根反复红烂，还需减潮湿与摩擦。汗疹、间擦疹及继发感染不是同一回事，爽身粉或止痒膏不能包治。几天不改善、渗液疼痛破损或反复发作，应检查后再选药。',
'汗疹常是热汗后的刺痒小疹；间擦疹是褶皱处因温热、潮湿、摩擦发炎，也可能继发感染。不是所有热天皮疹都叫痱子，不能只凭止痒广告选激素复方。[@0][@1]\n\n**小疹先降温、换宽松衣，短时凉敷，少抓挠和强香护理。** 褶皱清洁后轻吸干，换湿衣并减摩擦。[@0][@1]\n\n几天无改善、诊断不清，或反复红烂、渗液、痛，应检查是否需抗真菌、抗菌或抗炎。粉剂不能纠正感染，不把不同病因用同一瓶爽身粉遮过去。[@0][@1]',benefit='分清热、汗、摩擦及感染，减少闷湿和盲目试药。')
add('bodyskin-008','痣变样、出血或特别不同，先检查再美容处理',
'痣或斑点新变化、反复痒或出血，或明显不同于其他斑点，应先看皮肤科，再点痣、激光或脱毛。可拍带日期照片比较边缘、颜色和大小，但小于6毫米也不能保证安全。不要用腐蚀药或光电先改变外观，免得丢掉诊断线索。',
'ABCDE是痣的提醒线索：不对称、边缘不规则、颜色不均、直径偏大和持续演变，不是确诊或排除规则。小于6毫米也可能有问题；新生、特别不同、反复痒或出血都值得检查。[@0]\n\n**先预约皮肤科，留带日期照片帮助记录，不先烧掉或点掉。** 医生按需要决定皮肤镜或取样。准备激光、强脉冲光（IPL）等美容时，先展示可疑病变；光电可能改外观、掩盖判断线索，不用网购腐蚀药或脱毛仪试治。[@0][@1]',benefit='保留诊断线索，避免把疾病当美容瑕疵遮掉。')
add('bodyskin-023','风团伴口舌肿或气短晕厥，立即急救',
'突然隆起、很痒又会消退的痒块可能是荨麻疹；伴面口唇咽喉肿、呼吸吞咽困难或明显眩晕，立即急救。轻症可询问药师合适抗组胺药，不自行加倍叠药。反复或大面积要就诊，记录单块持续多久，不直接买过敏套餐或大范围忌口。',
'**风团伴面部、口唇、咽喉肿胀，呼吸吞咽困难，明显眩晕或将晕倒，立即联系急救或急诊，不等涂药。** 风团是突然隆起的痒块，可能是荨麻疹。[@0]\n\n轻度风团可用适合的抗组胺药缓解症状；这不是排毒，也不意味着病因全是食物过敏。大面积、持续或反复，尤其超过6周，需皮肤科评估。[@0]\n\n**轻症向药师问较少嗜睡的适用品种，按本地说明，不加倍、叠多种。** 儿童、孕哺和并用药另核。拍疹子、记单块何时消退，及新药、感染、运动冷热等；让病史指导检查，不盲目做全套过敏原或长期忌口。[@0]',benefit='识别严重反应，让反复风团获得针对处理。')
add('bodyskin-024','夜里痒、同住者也起疹，检查疥疮并同步处理',
'夜里特别痒、指缝腕部腰臀等起疹，同住或密切接触者也痒，应检查疥疮。它不是洗不干净，普通除螨沐浴露和杀虫喷雾不能治。确诊后按医嘱用药、同步处理接触者和衣被；治后痒可延续几周，新疹或2至4周仍痒需复评。',
'疥疮是疥螨寄生造成的皮肤病，常见夜痒，指缝、腕、腰臀和生殖器周围起疹；这些表现也可能来自湿疹等，不能自诊。[@0]\n\n**有线索时到皮肤科说明同住和密切接触史。** 确诊后问清外用或口服药的部位、停留时间、重复安排，家庭及密切接触者按医嘱同时处理，包括尚未痒的人。儿童孕期不照成人方案，不靠搓澡、沐浴露或身体喷杀虫剂。[@1][@2]\n\n近期衣物、寝具、毛巾按指导热洗烘干，不可洗者密封数日至一周。痒可持续几周，不自动等于失败；新疥道、新疹、感染或超过2至4周仍痒复评，不无限重复用药。[@1][@2]',benefit='减少接触者漏治和反复传回，避免无效杀虫暴露。')
add('bodyskin-012','浅擦伤冲洗后湿润覆盖，别反复灌酒精',
'清洁浅擦伤先止血、清水冲洗，再薄涂凡士林和干净敷料，脏湿了就换。适度湿润不是泡水，也不是把祛疤贴贴开放伤口；干净小伤不必一律涂抗生素。深伤、咬伤、异物或感染不适用简单自护，需医疗处理。',
'湿润愈合是用合适覆盖避免创面干裂，不是长泡水或闷在脏湿敷料里。反复灌酒精、双氧水会刺激组织；闭合瘢痕用的硅酮贴也不是开放伤口敷料。[@2][@3]\n\n**清洁浅擦伤先止血，用自来水或瓶装清水冲洗，清洁周围皮肤；薄涂凡士林、干净覆盖，日常查看并换脏湿敷料。** 不必每个干净小伤都加抗生素软膏，伤口长好后再防晒帮助减色差。[@0][@1]\n\n需缝合、烧伤、咬伤、异物或感染，转[伤口就医入口](#/entry/bodyskin-001)，不继续套简单护理。[@0][@1]',benefit='保护浅表伤口，减少反复刺激和不必要药膏。')
add('bodyskin-025','犬猫咬抓伤先冲洗约15分钟，尽快评估暴露',
'动物咬抓伤、唾液接触破皮或黏膜，尽快到狂犬病暴露处置门诊，不能凭未流血或宠物健康自行排除。普通皮肤伤尽早用肥皂水与清水交替冲洗约15分钟；眼部、深伤、头面伤及时医疗处理，止不住血先急救。疫苗和现成抗体由暴露评估决定。',
'**动物咬抓伤，或唾液接触破皮、黏膜，先处理伤口，尽快去狂犬病暴露处置门诊。** 轻微抓伤未出血也可能需处置，接触蝙蝠等也要说明，不凭动物看着健康排除。[@0]\n\n狂犬病暴露处置按暴露分级等决定疫苗和被动免疫制剂；后者提供现成抗体。抗生素、消毒不能代替必要预防，不等发病或感染才就诊。[@0]\n\n**普通皮肤伤尽早用肥皂水与流动清水交替彻底冲约15分钟，再冲净。** 眼部不灌肥皂或消毒剂，深伤、头面伤尽快就医；大量出血压不住先止血急救，不为凑冲洗时间耽误。带受伤时间、动物种类、部位、既往疫苗和免疫病资料，兼评破伤风与伤口处理。[@0][@1]',benefit='让容易误当小伤的暴露及时接上规范预防。')

add('sleep-001','开车犯困就安全停车，不靠提神办法硬撑',
'眼皮撑不住、反复压线、漏看路标或记不起刚开的路，就该安全停车，换清醒驾驶者或其他交通。咖啡和短睡可能暂时提神，不保证恢复驾驶能力；醒后仍困就不继续开。睡够还反复失控打瞌睡，带作息和用药记录就诊。',
'**眼皮撑不住、反复压线或漏看路标，尽快到合法安全地点停车，换清醒驾驶者或其他交通。** 开窗、拍脸、音乐、能量饮料都不能代替睡眠。[@0]\n\n困倦时，咖啡加约20分钟短睡有时仅暂时提高警觉，不能证明驾驶能力已恢复；醒后仍困就不继续开。夜班返程事先安排，药品嗜睡警示也要看。[@0]\n\n睡眠机会已足够却仍反复不受控打瞌睡或发生险情，带作息、用药记录到睡眠或相关专科。打鼾憋醒另查[睡眠呼吸暂停](#/entry/basics-002)，不只换提神用品。[@1]',benefit='避免把短暂清醒误当可以安全驾驶。')
add('basics-002','鼾声伴憋醒或白天困，检查睡眠呼吸暂停',
'打鼾时有人见到呼吸停顿，自己反复憋醒或白天很困，需要睡眠评估，不能只买鼻贴或贴嘴。鼻部通畅不等于整个气道问题解决；贴嘴研究小、质量低，鼻堵者尤其不宜自行试。确诊后按严重度选择治疗，困得影响开车就停驾。',
'睡眠呼吸暂停是睡着后呼吸反复停止又恢复，阻塞性类型涉及气道变窄。鼾声合并呼吸停顿、憋醒或日间困倦应评估；可请同住者描述，必要时整夜监测，不靠鼾声录音确诊。[@0][@1]\n\n鼻贴只可能帮助部分鼻部阻力。2025贴嘴综述研究小、质量低、结果不一致，部分鼻堵者被排除；不能推广给所有张口睡的人，也不能把风险直接写成人人必窒息。[@2][@3]\n\n**有线索先到睡眠、呼吸等门诊，不自行贴嘴或网购通用止鼾牙套。** 确诊后可讨论持续气道正压（CPAP），即面罩送气保持气道开放，或其他适合治疗。困到影响驾驶时停驾；儿童另按儿童方案。[@1][@4]',benefit='识别可治疗的睡眠疾病，避免用品只掩盖鼾声。')
add('sleep-016','夜里静坐就想动腿，记录规律，别盲目补钙铁',
'休息时腿里难受、夜里更重、动一动暂缓，可能是不宁腿，不能直接当抽筋、缺钙或缺铁。记录时段、诱因和药物，影响睡眠就到全科、神经或睡眠门诊。轻走伸展可暂缓，检查铁储备不代表人人需补铁，更别按网帖自己吃铁打针。',
'不宁腿综合征（RLS）是在静止时强烈想动腿、伴不适的睡眠相关问题，常夜里更重、动后暂缓。抽筋、周围神经问题也可能相似，一次腿痒不能确诊。[@0][@1]\n\n医生可能检查铁蛋白、转铁蛋白饱和度等铁储备指标，并看疾病和加重药物。检查铁不等于必须补铁；是否治疗还需结合结果、基础病及孕哺状态。[@2]\n\n**记录“休息重、夜里重、动后缓”的规律，影响睡眠就就诊。** 发作可轻走、轻伸展或按摩暂缓，带咖啡因、酒精和药单，尤其感冒、过敏及精神科药；不自行停处方，不按化验网帖吃铁打针，也不用钙镁或按摩仪代替评估。[@0][@2]',benefit='为常被当成缺钙的小困扰找到合适的检查入口。')
add('basics-001','稳定起床时间，留够睡眠，不追统一8小时',
'成人通常可参考每晚7至9小时，但需求会变，补觉恢复或生病睡久些未必有害。先稳定起床、留够睡眠机会，记录入睡夜醒和白天清醒程度。习惯调整仍不好、持续数月或已影响生活，就评估原因，不用酒精、助眠产品或手环分数替代判断。',
'睡眠需求因人和状态而异。成人可参考每晚7—9小时；年轻成人、补觉恢复或生病时超过9小时未必有害，不能拿8小时作统一考试。[@0]\n\n**尽量稳定起床时间，给自己留够睡眠机会，睡前留收尾时间，卧室暗、安静。** 记录入床、入睡、夜醒和日间困倦，比一次手环分数更能描述问题；难睡不靠提前许多小时上床硬熬。[@1]\n\n调整仍不好、持续数月或已经影响生活，就到睡眠或相关门诊，不必硬等。治疗可处理维持失眠的想法和行为，并非劝想开；不自行长期叠药、补剂，困倦不驾车。[@1]',benefit='把作息调整落到白天功能，减少追求完美数字的焦虑。')
add('sleep-008','白天适当见自然光，别把暴晒当情绪治疗',
'通常夜睡昼起的人，可起床后适当到户外、白天活动，睡前减少强光；目标是合适时机见光，不是晒伤或直视太阳。夜班时差另安排。若情绪和睡眠随季节反复明显改变、影响生活，需要评估，普通日晒不能替代有适应证的灯箱治疗。',
'光会影响生物钟，晨间与晚间作用方向不同；普通户外见光和医学灯箱治疗不是一回事，不规定人人同一晒太阳时长。夜班、时差也不能照搬晨光安排。[@0][@1]\n\n**平常夜睡的人，起床后适当户外活动，白天走动、睡前减强光，照常防晒，不直视太阳。** 心情暂时不好，出门可作舒适的日常选择，不能保证治疗情绪问题。[@0][@1]\n\n若每到某季节反复低落、睡眠食欲改变并影响生活，评估是否季节性情感障碍等。临床灯箱滤紫外线，并有时机剂量要求；眼病、光敏药尤其需监督，不用紫外灯、晒黑灯或暴晒替代。[@2]',benefit='用合适环境光支持节律，同时不延误持续情绪异常。')
add('sleep-005','晚间难睡就提前咖啡因，别用酒助眠',
'咖啡、茶、可乐、能量饮料等都要算进咖啡因摄入。若夜里难睡，先把末次摄入提前到预计睡前约8小时或更早，记录是否改善，这不是人人相同的安全线。酒精虽可能催困，却会使后续睡眠更浅碎，也别和镇静药或褪黑素混用。',
'咖啡因影响可持续到8小时，个体差异大，来源不只咖啡，还有茶、可乐、能量饮料和部分巧克力。酒精可能使入睡快一些，却让后续睡眠更浅、易醒，不适合当助眠护理。[@0][@1]\n\n**难入睡时，先把最后一次咖啡因提前到预计睡前约8小时或更早，连续记录变化。** 这是调整起点，过8小时不保证无影响，也不能只按杯数算剂量。夜班需要提神，可尽量放班次前半段，为下班睡眠留空间。[@0]\n\n不靠晚安酒换睡眠，已用镇静助眠药或褪黑素时不自行混酒。全天总量另看[咖啡因](#/entry/energy-001)。[@1][@2]',benefit='减少入睡困难和夜醒，不让提神侵占下一段睡眠。')
add('sleep-006','午睡短一些、早一些，夜班先保护主睡眠',
'普通日间小睡可从较早下午约20分钟试起，醒后舒服、晚上也睡得着才适合；夜里难睡就提前或减少。夜班要先保住白天主睡眠，不靠咖啡和碎觉顶替。醒后迟钝未过别开车操作机器；持续班上困、白天睡不着，应带班表评估。',
'短小睡可暂缓困倦，但醒后可能有睡眠惯性，也就是暂时迟钝。普通午睡与夜班主睡眠不同；2026成人轮班障碍指南对部分小睡、褪黑素选择仅有低或很低确定性证据，不是一套通用调班方案。[@0][@1]\n\n**普通日间小睡先试较早下午、约20分钟，设结束提醒，看当晚睡眠。** 若越睡越晚、晚上更难入睡，提前或减少；不把成人参考当所有年龄硬限。[@0]\n\n夜班先护下班主睡眠，遮光降噪，咖啡尽量前半班。计划小睡后留清醒时间再开车上机。频繁轮转未必能完全调钟，持续过困或睡不着带班表、记录就诊，不自行叠大剂量褪黑素、强光和提神药。[@0][@1]',benefit='缓解短时困倦，同时保留主睡眠和返程安全。')
add('sleep-009','晚间锻炼看强度和睡觉时间，难睡就提前减量',
'晚练没有统一八点九点截止线，要看距入睡多久、强度和时长。临睡前选轻活动；若晚练后总发热、心跳难平、睡不着，可先把较重训练提前到睡前约4小时结束，或减短减轻。4小时是试调起点，不代表线内任何活动都有害。',
'晚练影响不能只看钟点：强度、时长和距入睡多久都重要。大型可穿戴观察研究的约4小时参考是相关性，不是生理开关；良好睡眠者的小实验综述中，睡前2–4小时结束高强度运动总体未见明显恶化，也不能保证老年或失眠者。[@0][@2]\n\n**从预计睡觉时间倒推，不为训练继续挤睡眠。** 临睡选轻走或温和活动；若练后常发热、心跳难平或难睡，先把较重训练提前到约4小时前结束，记录时间强度与睡眠。只能晚练就缩短、降强度。[@0][@1]\n\n机构睡眠建议会因人群和目标有差异，并非一致禁令；失眠者可优先提前较重训练，持续影响白天就[评估失眠](#/entry/sleep-002)。胸痛、晕厥或明显气短按[运动急症](#/entry/activity-001)求助，别只当兴奋。[@1][@3]',benefit='保留可持续运动，同时减少高负荷与挤睡眠的困扰。')
add('sleep-010','夜宵后睡不好，先把大餐提前，反流另留间隔',
'睡前吃撑与饿着睡都不必硬扛。把大餐前移，若只是饿可少量吃自己耐受的普通食物，并记录分量、时间、反酸和夜醒。反流者可试睡前2至3小时不进餐，这不是人人统一禁食线；降糖方案安排的加餐不能自行删掉。',
'夜宵的影响需同时看分量、时点、反流和个人反应，不能全归为消化慢。直接睡眠试验小且结果不一，不能说所有夜宵都破坏睡眠；胃内容物回食管造成的反流，则可能引起烧心、酸水。[@2][@3][@1]\n\n**先把临睡大餐提前几小时，饿时可少量选耐受食物，不额外买助眠零食。** 记吃什么、多少、几点和反酸夜醒，观察调整效果。反流者可试睡前2–3小时不进餐，ACG对此是低确定性条件建议，不是所有人禁点心；按自身触发食物调整，不照抄全套忌口。[@0][@1]\n\n反复反酸或吞咽卡住按[反流入口](#/entry/abdomen-006)检查，新明显胸痛别只当胃病。失眠持续按[睡眠评估](#/entry/sleep-002)处理。胰岛素或易低血糖药使用者，不自行删计划加餐、改药或久饿；夜汗、噩梦、醒后异常可核血糖并按既定方案处理。[@1][@4]',benefit='减少过饱和反流不适，同时避免误删必要加餐。')

add('sleep-011','睡前给工作和刷屏收尾，夜间模式不保证助眠',
'睡前越刷越清醒，可从睡前30至60分钟结束工作、减少屏幕和强光试起，写下待办、关提醒，给睡觉留时间。无需强迫情绪零波动。夜间模式只改部分光线，没减少聊天追剧；防蓝光眼镜也没有确定助眠保证，持续失眠要评估。',
'蓝光是可见光中较短波长部分，但屏幕影响还包括亮度、使用时长、内容和挤睡眠。最大亮度平板连续几晚睡前约四小时的实验，不能等同短看手机。[@3][@0]\n\n睡前停手机的小试验有部分改善，样本小且受监督；夜间模式试验未见总体睡眠改善，滤蓝光镜片的睡眠收益仍不确定，不必先买眼镜。[@2][@4][@5]\n\n**从睡前30–60分钟收尾试起：停会刷久的内容、写待办、关多余提醒，再轻松阅读或安静音频。** 不强求情绪完全平静；手机可放远但保留必要联络。临时必须用就缩短、减刺眼亮度后放下；持续困扰走[失眠评估](#/entry/sleep-002)。这个时段不是统一生理截止线。[@0][@1]',benefit='给睡眠腾出时间，减少临睡持续处理事务。')
add('sleep-014','越躺越烦就暂离床，困了再回来，不盯钟',
'短暂醒着但躺得舒服，不必马上起床；越躺越清醒、烦躁时，可到安全地方做点安静的事，困了再回床。不设20分钟倒计时，不把离床当惩罚。反复失眠纳入完整治疗；用镇静药、行动不便或易跌倒者，先调整夜间安全做法。',
'刺激控制是减少床与长时间清醒、懊恼、努力入睡的联系，重新让床联系睡眠；它不保证离床一次就能睡着。疲劳和困倦也不同，不必只是累就提前许多小时上床。[@1][@2]\n\n**躺着舒服可继续休息；越躺越清醒烦躁，就转开钟面，暂去安全处坐着，轻松纸书或安静内容，困了回来。** 不必盯20分钟倒计时，也别转去加班、激烈运动或刷屏。[@0][@1][@2]\n\n夜间保留防跌倒照明。已用镇静药、行动不便或易跌倒，先与治疗者调做法，别在黑暗里硬走。反复影响白天走[CBT-I](#/entry/sleep-002)，不自行加码整夜不睡或大幅压缩睡眠。[@2]',benefit='减少在床上硬等和烦躁，给失眠提供具体应对。')
add('sleep-002','失眠影响白天，记录睡眠并了解CBT-I治疗',
'有时间睡却反复难入睡、易醒或早醒，并影响白天，应记录作息后评估。成人慢性失眠的一线选择是CBT-I，包含睡眠安排、刺激控制和认知调整，不只是放松音乐或早睡清单。不要自行大幅限睡，尤其需要开车或已有明显困倦时。',
'失眠认知行为治疗（CBT-I）由受训人员调整睡眠安排、床与睡眠的联系、放松及对睡不着的担忧，是成人慢性失眠优先选择的完整治疗，不是劝想开或只给早睡清单。[@1][@2]\n\n**先记一到两周上床、大概入睡、夜醒、起床、午睡、咖啡酒精和白天困倦，带去评估。** 日记能帮助分清睡眠机会不足、生物钟错位和失眠，并提示打鼾、疼痛或药物线索。[@0]\n\n可比较面对面或合适线上CBT-I，音频App不自动等于完整治疗。不要照网帖自己大幅压缩睡眠，已有明显日困或需要开车时先讨论安全；别一直靠换枕头、香薰和补剂拖着。[@1][@2]',benefit='得到针对失眠的治疗，不只反复尝试助眠用品。')
add('sleep-003','褪黑素先分用途剂型，别靠加量治所有失眠',
'褪黑素传递夜晚和生物钟信号，不是所有失眠都缺它。先分普通失眠、时差或节律问题，再看每份毫克和速释缓释。中国相关保健食品每日1至3毫克是标签范围，不是人人需补的处方；别叠多款、混酒或用进口高剂量自行升级。',
'褪黑素是黑暗中分泌、参与睡眠时序的激素。普通速释保健品不是成人慢性失眠一线治疗；晚睡晚起、时差，以及特定缓释处方是不同用途，不能把某一方案给所有软糖背书。[@0][@1]\n\n**先查国内注册备案，算一次几份、每份多少mg和全天总量。** 国内相关目录每日1–3mg，按具体标签与专业建议，不追进口10mg或多款叠吃。头晕、日困或影响生活就停自行加量并复评；不成瘾不代表长期、混酒、超量安全。[@2][@0]\n\n速释缓释的时机与人群不同：EMA Circadin 2mg缓释处方用于符合适应证的55岁及以上者，餐后睡前1–2小时、最长13周、整片吞服；不能搬给中国任意保健品。未成年、孕哺备孕不自行套成人；抗凝、抗癫痫、镇静药、自身免疫或肝肾病先问相互作用，服后困不驾驶。[@3][@0]',benefit='让用途、剂型和用量相符，减少叠加与持续病因被掩盖。')
add('sleep-004','倒时差先排睡眠见光，褪黑素不能随时补',
'跨时区后白天困、夜里醒，往往是生物钟还没对齐。按目的地、方向和停留时间安排睡眠见光，再决定是否用褪黑素。吃错时点可能越调越乱，不能按北京时间固定补、半夜反复补或靠大剂量还睡债，准备开车前也不用。',
'时差是内部生物钟与目的地时间不合，表现可为白天困、晚上醒。出发前几天可逐步靠近目的地作息，到后按当地进餐、睡眠和适当见光；短停留是否调，取决于行程。[@0]\n\n褪黑素可帮助部分成人调时相，但吃错时机可能加重错位。CDC成人时差参考约0.5–1mg常已足够，不推荐超过5mg；这不是中国保健食品标签或人人自用剂量。[@0][@1]\n\n**带方向、时区、到达时刻和原作息，向医生或药师确认时点、剂型与服后安排。** 不用长时间白天补觉冲掉夜间睡意，也不因一晚没睡着半夜重复补，更不在准备驾驶前用。[@0]',benefit='按节律需要适应行程，减少错误用药时点带来的困倦。')
add('sleep-015','别长期用感冒抗过敏药催眠，次日困就不驾车',
'部分夜用感冒药、抗过敏药和助眠片含镇静抗组胺成分，犯困不等于适合长期治失眠。先看有效成分，别为睡觉吃进无关复方药，也不叠药配酒。老年、闭角青光眼、排尿困难等先问风险；服后仍困、站不稳，不开车。',
'苯海拉明等镇静性抗组胺药可用于部分过敏，也可能出现在夜用感冒、止痛和助眠片里。它让人困，不等于适合长期治失眠；久用镇静可能变弱，指南对慢性失眠常规使用仅作弱反对，不能说所有短期或过敏用途都无效。[@0][@1][@2]\n\n**先看有效成分，不为困意顺带吃不需的退热止痛药，不叠相同成分、不配酒或其他镇静药。** 反复不好睡走[失眠评估](#/entry/sleep-002)，不自行停治疗其他病的处方。[@0][@1]\n\n服后头晕、站不稳、次日困就不驾驶。老年、闭角青光眼、排尿困难、肝肾或呼吸问题者，带全药单问医生药师；儿童和孕哺不照成人自购催眠方案。[@0][@3][@1]',benefit='避免追困意造成重复摄药、次日警觉和跌倒问题。')
add('sleep-007','睡前音频开低音量定时，耳机压痛就停',
'先分需要放松还是隔音，环境能安静就不必整夜加声音。想听时低音量、定时停播，必要时试合适外放或清洁耳塞；入耳耳机压痛、耳内潮湿或痒痛流液就别硬戴。白噪音和睡眠耳机没有通用助眠保证，还要听得见重要警报。',
'助眠声音不一定改善睡眠。2026年25名成人、七夜实验中，特定粉红噪音减少REM睡眠，耳塞较能缓解环境声影响；不能推成所有雨声有害或某款耳塞长期最佳。听觉风险还看音量与时长，不由手机60%滑块、降噪或骨传导保证。[@2][@1]\n\n**先解决环境噪声，想放松再低音量、定时听一段，必要时合适外放并顾及同住者。** 隔音可试清洁、适配耳塞，仍需听见警报，不追求整夜大声覆盖。[@0][@1]\n\n侧睡耳机压痛、洗后耳内潮湿、痒痛流液时停戴；耳痛、耳鸣、听力变化停用检查。用实际睡眠判断是否留用，不把整夜入耳当必需。[@0]',benefit='保留喜欢的放松方式，减少声暴露和耳道刺激。')
add('sleep-012','少睡次日先保安全，安排短休息和当晚睡眠',
'昨晚少睡后，明显打盹或反应慢就改通勤、停危险任务，别用咖啡后的清醒感证明能开车。白天按需早些短睡，醒后缓过迟钝再做事，晚上留足睡眠。咖啡算总量不叠浓缩饮料；恢复有用，但一次补觉不保证抹掉连续缺觉的影响。',
'**明显打盹、反应慢，先取消改派危险任务，改乘公共交通或请清醒者驾驶。** 通宵先找安全休息处，不为守作息强撑；开窗音乐和浓咖啡不是驾驶许可。[@0]\n\n恢复睡眠有用，但感觉好些不等于注意力等全恢复，一次补觉不能保证抵消反复缺觉。年轻成人或还睡债时可能需更长睡眠，没有人人一样的补觉时数，也不机械封顶8小时。[@2][@5]\n\n**按需安排较早约20分钟短睡，醒后等迟钝过去；尽量保留起床与主睡眠框架，今晚留足机会。** 反复难入睡者可缩短提前午睡，少睡到傍晚。惯常咖啡不必自动全禁，但400mg不是缺觉加量目标；算每份及全天量，不叠能量饮料和训练补剂，心悸手抖就别续。反复影响生活及时[评估失眠](#/entry/sleep-002)。[@1][@3][@4]',benefit='减少缺觉后的危险任务与刺激循环，给恢复留下空间。')
add('sleep-013','少睡后困得打盹就休息，别硬上大强度训练',
'通宵、连续打盹或动作控制变差时，先休息，取消极限、大重量和高后果项目，不困着开车去健身。偶尔稍少睡但清醒、无不适，可改成熟悉轻活动、缩短减量；不是人人必须卧床。咖啡不证明协调恢复，也别为了晨练再次缩睡眠。',
'少睡会影响反应、判断和动作表现，任务与个人差异很大；“感觉撑得住”不能证明安全，也没有按睡几小时统一开训练的处方。[@0][@1]\n\n**通宵、接连打盹或难集中时先休息，取消极限、大重量测试及失误后果大的训练，不困驾。** 偶尔少睡但仍清醒无不适，可换成熟悉、轻松、短些的活动；更困、控制变差或不舒服就停，不用累垮自己来催睡。[@0][@1][@2]\n\n不靠浓咖啡、能量饮料或训练前补剂顶回强度，也不为研究里晨间表现较好就早叫醒晨练。胸痛、晕厥、明显气短按[运动急症](#/entry/activity-001)处理；连续多晚睡少，先解决睡眠而非长期每天降级。[@2][@1][@0]',benefit='让训练服从警觉与恢复，不用提神产品冒充补足睡眠。')

add('nutrition-001','节食后发抖先停，意识异常或深快呼吸立即急救',
'节食运动中发抖、冷汗、心慌或头晕，先停下到安全处，不开车。糖尿病者测血糖、按既定方案处理，只有清醒且能吞咽才口服快速糖；意识异常拨120，不能喂糖水。呕吐腹痛、深快呼吸或嗜睡也须急诊，服格列净类时血糖不高仍可能危险。',
'**发抖、冷汗、心慌或头晕，先停止禁食和运动，到安全处坐下或躺下，不驾车。** 不适不自动等于低血糖；胰岛素或部分降糖药使用者，漏餐少吃碳水会增加风险。测血糖后，低于个人处理阈值或出现熟悉症状，清醒且能吞咽才按既定方案用快速糖、复测，无糖饮料不能补糖。[@0]\n\n意识异常、抽搐或昏迷立即拨120，不往嘴里塞食物、糖水或凝胶；有预先处方胰高血糖素且施救者受训，按既定方案用。非糖尿病反复不适也需查原因，不总靠吃糖。[@0]\n\n**持续呕吐、腹痛、深快呼吸、异常嗜睡或混乱，立即急诊。** 酮症酸中毒是酸性物质危险积累的急症，不是生酮适应期。达格列净、恩格列净等SGLT2药在久禁食、极低碳水、脱水时有风险，血糖不高不能排除。带药单就医，不因没吃饭自行停胰岛素。[@1][@2]',benefit='区分可处理的不适和代谢急症，避免为掉秤拖延。')
add('basics-004','先把日常饭吃完整，再决定是否补蛋白或代餐',
'一日餐食先有主食、蔬果和豆蛋奶鱼肉等蛋白来源，别只靠青汁或一种超级食物。蛋白粉可补实际缺口，不比正常食物更高级；普通奶昔、青汁和维生素糖也不是完整一餐。按年龄、训练和疾病选择，极低热量全代餐需专业支持。',
'蛋白质参与肌肉等身体结构；膳食纤维是不能完全消化的食物成分，可从全谷、豆和蔬果获得。蛋白粉只是便利补充，不因吃够后再加就自动更健康，果汁也不同于完整水果。[@0][@1]\n\nWHO2026给10岁以上每天至少400克蔬果、25克天然食物纤维的参考，本条用于成人，不代替儿童或疾病营养方案，也不是再加25克纤维粉。[@0]\n\n**先查餐食是否多样、总量适合，再决定补哪里。** 主食、蔬果、豆蛋奶鱼肉组合，不必昂贵或靠超级食物。蛋白粉、青汁和维生素糖不自动成为完整一餐；低热量全代餐需专业支持，肾病、吞咽或吸收问题另评估。[@1][@2]',benefit='让补充品填实际缺口，而非挤掉完整饮食。')
add('nutrition-013','一餐先配齐蔬菜和蛋白，把部分精白主食换全谷',
'不用一夜间戒白饭：先在一餐加少量糙米、燕麦或杂豆，同时留出蔬菜和鱼蛋豆肉位置。一天安排完整水果与适合的奶制品，别让果汁青汁代替。纤维逐步加，腹胀就看耐受；已有治疗性膳食按个人方案，不为粗粮强灌水。',
'全谷保留麸皮、胚芽、胚乳，比精白谷物保留更多纤维等成分；颜色深不代表全麦。中国2022核心推荐成人每天新鲜蔬菜至少300克、深色约半，水果200–350克，奶制品相当于至少300毫升液态奶，供查漏，不是逐口考核。[@0][@1]\n\n**先改一顿熟悉的饭：白米混少量糙米或杂豆，部分白粥换原味燕麦，再加蔬菜与鱼、蛋、豆制品或瘦肉。** 是替换部分饭量，不额外再加一碗。蔬菜分午晚餐，水果选完整食物；奶看实际乳含量及耐受，奶茶、果汁和青汁不自动替代。[@0][@1]\n\n忙时可用无过量盐糖的冷冻蔬菜、罐装豆和普通奶。原先少纤维者逐步加，结合需要补液，观察腹胀排便；不突然猛吃麸皮纤维粉。限钾、低渣等治疗性饮食先按方案，饮水见[日常补水](#/entry/basics-005)。[@2]',benefit='用能买、能安排的食物补齐餐食，而不只删主食或买补剂。')
add('nutrition-012','低钠钾盐不是人人能换，减盐也要算酱料零食',
'含钾低钠盐可供合适成年人替换烹调盐，但仍要少放，并计算全天食物、酱料和外卖的钠。肾功能异常、高血钾、补钾或相关用药者先问医生药师；儿童孕妇未纳入WHO这项建议，不直接整锅换。选盐兼顾加碘，不自配氯化钾粉。',
'低钠钾盐用氯化钾替代部分氯化钠，仍含钠。WHO2025是对合适成年人的条件推荐；排钾受限者不在范围，儿童、孕妇因证据不足未纳入，不等于已证实有害。SSaSS主要研究既往卒中或老年高血压农村高风险人群，不能承诺年轻人的个人收益。[@0][@1][@6]\n\n**先查病史和药单。** 肾功能损害、高血钾、补钾或保钾利尿剂，不自行换；“普利”“沙坦”类也可能有风险，由医生药师结合肾功能血钾判断，不为换盐停药。共餐有儿童、孕妇或高风险者，不直接全锅换，不自己配氯化钾。[@0][@2][@3]\n\n成人全天钠少于2000毫克，约5克盐，已包括食物、酱油蚝油、腌菜、零食外卖；400毫克钠约1克盐，按标签每100克及实际吃量换算。减少盐酱，辅以葱姜醋调味；选盐看钠钾和加碘，低钠不等于无碘，高水碘或特别限碘者另按方案。[@4][@5]',benefit='减少总钠，同时避免忽略排钾风险与碘营养。')
add('nutrition-014','买食品看营养和吃量，不因包装或添加剂一律排除',
'精白米面和超加工是不同分类，有包装、冷冻或罐装不自动不健康。比较同类食品糖盐脂肪、纤维及实际分量，少让甜饮零食挤正餐。菜单试验不能证明单一添加剂有毒；中国标签新标2027年才实施，2026年没列糖不能当无糖。',
'精制谷物是去掉较多麸皮胚芽的米面；NOVA超加工则按工业成分、配方和加工目的分类。两者不是一回事，白米饭不因精制就等于超加工，成分有乳化剂防腐剂也不能直接推出致病。[@0][@1][@2]\n\n2019年20名成人交叉喂养试验中，超加工菜单阶段吃得更多；2025英国每套各8周的试验，两套都符合当地膳食建议、都平均减重，较少加工菜单下降更多。它们比较整套短期饮食，不能归因单一添加剂或承诺戒一包食品就瘦。[@3][@4]\n\n**同类按每100克/毫升比较，再算实际吃掉多少。** 少让甜饮、咸零食、甜点、加工肉作主力，保留普通奶、燕麦、合适冷冻菜和罐头等便利食物。中国将糖和饱和脂肪强制列项的新标于2027年3月16日生效；2026年10月的未标糖不等于无糖，仍看配料与吃量。[@0][@1][@5]',benefit='减少过量糖盐能量，同时保留方便、能负担的健康食材。')
add('basics-005','饮水按口渴、天气和活动调整，限水者另按方案',
'喝水是补所需液体，不是越多越排毒。规律喝，结合口渴、热天和出汗调整；淡黄尿色只是粗略线索，不追永远透明。食物和其他饮品也贡献水分。心衰或部分肾病已要求限水，汤冰等也计总量，不照搬八杯、1升或大水壶挑战。',
'身体所需液体来自饮水、部分饮料与食物；没有人人同一杯数。英国6—8杯是一般参考，不是各种杯子和体型的统一处方，淡黄尿色也不能诊断疾病。[@0]\n\n**日常规律喝，按口渴、热环境、活动和出汗调整，不为排毒强灌。** 普通活动不默认需电解质饮料或功能水，先看场景及糖盐。持续吐泻、明显脱水或大量出汗需另评估，不能只套一般补水。[@0]\n\n心衰或部分肾病有液体潴留者，按团队给的总液体方案，汤、冰和含水食物也可能算；不照别人限1升，也不自行少喝消肿。利尿药、尿色、出汗不能单独决定饮水量。[@1]',benefit='避免过量强灌或过度限水，减少无用途功能水消费。')
add('nutrition-015','餐后控糖先管饭量和饮料，饭后别一直坐',
'血糖餐后上升本身不是病，不要为追直线戒掉主食水果。用部分全谷杂豆替换精白主食，配蔬菜和蛋白食物，甜饮换水，久坐中轻走。先菜后饭可自选，不必计时；用胰岛素或促泌剂者，大改吃法和运动前安排监测，别把不适当成功。',
'血糖是血液葡萄糖，餐后上升不自动等于疾病；低GI（血糖生成指数）只描述升糖特点，不保证营养更好或无限吃。轻走打断久坐有当日血糖、胰岛素指标支持，不能由此承诺固定分钟数长期防糖尿病。[@0][@1][@2]\n\n**先盛好适合的主食量，用部分全谷杂豆替换精白饭，配蔬菜和鱼蛋豆，甜饮换水或无糖茶。** 果汁不代完整水果，饭后收拾再轻走，工作中也起身。不为消掉一餐马上猛练。先菜后饭可按偏好，小型糖尿病综述未确立标准饮食外的额外长期收益，不计时也不借机多吃。[@0][@1][@2][@3]\n\n胰岛素、磺脲或格列奈类使用者，不突然漏餐大减主食或猛加运动，先约监测、补食与联系调整方案。运动后低糖可延迟出现；发抖冷汗头晕心慌按[低血糖入口](#/entry/nutrition-001)处理，不自行减停药。[@4]',benefit='让餐食和活动更可持续，不为曲线牺牲必要营养。')
add('nutrition-016','担心血糖做正规筛查，消费手表曲线不能自诊',
'担心血糖先按年龄、体重、家族史和既往检查安排筛查，不先买传感器。中国行动方案提倡40岁及以上每年查空腹血糖，高危和糖前另有安排。口渴多尿、无故变瘦尽快检查；CGM可辅助特定患者，但健康人靠它防病抗老证据不足。',
'空腹血糖反映当次状态，糖化血红蛋白（HbA1c）反映约三个月平均，贫血等会影响解释；异常需规范化验与复核。CGM以皮下传感器估计组织间液葡萄糖，不是连续直接抽血。[@2][@3]\n\n**按中国2024—2030方案：40岁及以上每年至少一次空腹血糖，高危至少每年一次；糖前每半年空腹或餐后2小时血糖、每年风险评估。** 糖前是高于正常但未达糖尿病范围；未到40岁有超重、家族史或妊娠糖尿病史也应评估。口渴多尿、视糊或无故变瘦尽快就诊，不等体检；吐、深快呼吸、嗜睡等按[急症](#/entry/nutrition-001)处理。[@0][@1]\n\n需细致监测的患者可与团队讨论CGM，读数和感觉不符按说明及既定方案核实，不追曲线加药。健康人防病抗老证据不足，不因峰值戒水果。宣称独立无创测糖的表戒不用于诊疗，与显示正规CGM数据不同；FDA历史警告也不是当前全球准入清单。[@3][@4][@5]',benefit='让高风险者及时检查，也避免健康人为曲线盲目消费。')
add('nutrition-020','判断是否要减重，先看BMI、腰围和健康风险',
'体脂秤变红不等于需要继续减重。算BMI、按固定方法量腰围，再结合血压血糖、病史和体力；家用脂肪率肌肉量只是模型估算，不凭一天读数加餐停练。儿童、孕期、肌肉发达或虚弱老人不能套普通成人目标，药物门槛还需另核。',
'BMI是体重千克除以身高米的平方。中国普通成人18.5至不足24为正常、24至不足28超重、28及以上肥胖；它不能区分所有脂肪和肌肉，正常也不能排除腹部代谢风险，肌肉发达者可能被高估。[@0]\n\n家用体脂秤常用生物电阻抗（BIA）结合身高年龄推算，并非直接看见成分。2021三型号研究的体重表现优于脂肪肌肉估算，不能推出所有新款都差，也别因一天“掉1kg肌肉”就改吃练。[@2]\n\n**普通秤和软尺即可起步，相近条件看数周趋势、腰围与力量。** 软尺在肋骨下缘与髋骨上缘中点水平绕腹，自然呼气、贴合不勒。中国成人男≥90cm、女≥85cm达中心性肥胖界值，低于界值也非零风险。明显变化或血压血糖异常带记录评估；儿童看生长标准、孕期虚弱老年另定目标，药物见[适应证](#/entry/nutrition-017)。[@1][@0][@3]',benefit='先分清健康需要，减少被秤上估算数字牵着走。')
add('basics-010','体重管理先定健康目标，不照抄极端吃法和针剂',
'体重管理要结合腰围、病史、体力与营养，不只看体脂秤或追一个数字。确有减重需要再选可持续的吃动和支持；需要药物不等于意志差，但须按适应证随访。老年、偏瘦或进食困难先顾营养功能，不套减脂计划。',
'体重指数是体重与身高关系的筛查指标，不能分清所有肌肉和脂肪。治疗还需看腰围、代谢病、药物、功能及个人处境，不能凭一次体脂秤诊断。[@0]\n\n**先确认健康相关需要，再定可维持的饮食、活动和支持目标。** 极低热量全代餐仅适合特定医学条件，不能自己长期照做；需药物或专科支持不是意志力差，但要核适应证、风险与随访，不跟风买同款针。[@0]\n\n老年、体重低或吃饭困难先顾营养和功能。极端限制、失控进食或生活被体重占据时一并求助，不让掉秤速度成为唯一目标，外国门槛与别人的热量药量都不能直接套用。[@0]',benefit='减少极端节食和无指征用药，保留健康与功能。')
add('nutrition-021','减脂同时练力量，用腰围体力而非掉秤速度复评',
'有减重需要时，从两三件能坚持的饮食改变开始，同时安排有氧和力量训练。半年减初始体重约5%可作讨论起点，不是人人考核。抗阻有助保留去脂组织，却不保证多掉体重；每周看体重、间隔看腰围和体力，持续头晕无力应评估。',
'减体重、减脂肪与保肌力不是同一目标。2025年25项试验汇总显示，饮食减重加入抗阻可保存去脂体重、减少脂肪、改善部分力量，却未显示明显额外减体重；去脂还含水、器官骨骼，不全是肌肉，长期效果受坚持影响。[@1][@2]\n\n**确有减重需要，先选两三件能做的事：甜饮换水、少份高油配菜、保留主食但调量。** 可讨论6个月减初始体重约5%，有些方案5%–10%；正常BMI且无风险不照搬目标，达不到也非意志判决。正常主食蔬菜蛋白仍吃，加入按能力进阶的[力量和有氧](#/chapter/activity)。[@0][@1]\n\n相近条件每周记体重、间隔看腰围和走路训练表现，先看数周趋势，停滞不马上砍半饭或加倍练。持续无力头晕、训练倒退或总靠饿撑，回营养医疗评估；肥胖相关问题可讨论[药物](#/entry/nutrition-009)。[@0][@1]',benefit='减少多余脂肪时，兼顾营养和活动能力。')
add('nutrition-022','改善体型先分目标，别信练哪瘦哪或家用冻脂',
'练腹肌不保证指定消掉腹部脂肪。先分多余脂肪、肌肉不足和疼痛功能问题，再选饮食训练目标；正常体重无健康风险不必不断减。冷冻溶脂等只处理局部外观，不代替肥胖治疗，存在冻伤等并发症；家用安全有效性未建立，不用冰袋模仿。',
'局部肌肉训练能练那块肌肉，不保证周围脂肪按指定顺序减少。2022年13项单侧肢体研究汇总未显示局部减脂优势，但不能证明所有未来方案都绝无局部效应。[@1]\n\n**多余脂肪看整体吃动，线条和力量看循序全身抗阻。** 正常BMI无相关风险，不为一个部位不停减重；腰围、力量与能否持续比精准燃脂广告更有用。伴颈背痛、麻木或活动受限，按对应部位评估，不用减肥或通用矫姿代替治疗。[@0][@1]\n\n冷冻、射频是医疗塑形选择，不是肥胖或代谢治疗。选前核具体器械、操作资质与风险；冷冻可冻伤、持续麻木，少见反常性脂肪增生会变多变硬、有时需手术。家用安全有效性未建立，不冰袋仿做，FDA资料也不证明中国已注册。[@2]',benefit='把饮食、训练和医疗塑形用于各自目标，少花精准速瘦钱。')
add('nutrition-023','反复暴食催吐或不敢吃，停止补偿并尽早求助',
'反复吃得失控、强烈羞耻，又靠催吐、泻药、禁食或过度运动抵消，值得评估，不必等很瘦。进食障碍可发生于不同体重、年龄和性别。记录行为、体重和用药，寻求医疗营养支持；别继续挨饿或买更强抑食产品来惩罚自己。',
'进食障碍可能出现在不同年龄、性别与体重，正常或偏高也不能排除；反复失控进食、强烈羞耻后再催吐、泻药、禁食或过度运动值得评估，但不凭一两次行为确诊。[@0]\n\n治疗可包括医疗监测、营养支持与针对进食行为的心理治疗，不是归咎不自律。一般减脂打卡、体脂秤和减重药不能替代评估。[@0]\n\n**先别再增加惩罚性禁食运动或购买抑食产品，记录进食、补偿、体重变化和药物，尽早到全科、营养或精神心理相关门诊。** 反复催吐后已有身体不适不要只换食谱；既往有病史，新一轮减重前主动说明。[@0]',benefit='把正常进食和身体安全放在体重数字之前。')

add('nutrition-002','低碳可以选，严格生酮不是人人更优',
'生酮把碳水压得很低，和少喝奶茶不同，也不是多吃油就瘦。成人试验中，低碳与均衡减能量饮食一至两年平均减重差很小。若选择低碳，保留蔬菜纤维、看血脂和可持续性；用降糖药、孕哺或进食障碍等情况先评估，不自行减药。',
'低碳饮食程度不同；严格生酮把碳水降得更低，使身体更多产酮供能，不是油吃越多越瘦。成人随机试验综述中，低碳与均衡碳水减重饮食一至两年平均体重差小，初期快速掉秤也不全是脂肪。[@0]\n\n小型Keto-Med在糖前/2型糖尿病成人中，生酮未有更好主要血糖结局，同时LDL更高、部分营养摄入更低，不能当每个人必然结果。[@1]\n\n**选能持续、营养够的方案，不强迫进生酮。** 低碳也保留蔬菜纤维，不全用加工肉黄油奶油填空，记饱腹和耐受，有血脂问题计划复查。胰岛素、磺脲、格列净用药者大改前先安排监测与药物，不自停减；孕哺、偏瘦、进食障碍或复杂慢病先评估，医疗癫痫生酮另有方案。[@0][@2][@3][@4]',benefit='按营养、安全与能否坚持选择饮食，不追酮体数字。')
add('nutrition-003','限时进食看是否好坚持，饿到失控就换吃法',
'16:8、5:2和隔日禁食是不同安排，不是自动燃脂公式。成人试验提示它们可帮助部分人少吃，但长期没有一种稳定胜出。保留吃得够的正餐与蛋白，看精力、饥饿和训练恢复；头晕发抖、暴食或营养不足就停限制，特殊人群先评估。',
'16:8通常是一天8小时内进食，5:2是一周部分天限能量，隔日禁食又不同，不能互借疗效。2025年99项成人随机试验分析中，间歇禁食与持续限能量都比随意吃可减重；隔日有小幅平均额外收益，较长期未有一种稳定胜出，也未证明延寿排毒。[@0]\n\n**只在更容易安排、能吃够时选限时进食。** 保留正餐和蛋白，观察精力、饥饿、恢复和长期执行；若正常饭量被挤进短窗口、常饿到失控，换规律吃法，不用App逼延长。[@0]\n\n发抖、头晕或明显乏力就停限制并查原因。降糖药、孕哺、偏瘦、进食障碍史、年长体弱或进食不足，先个体评估；儿童青少年不套成人减脂窗口。[@1][@2][@3]',benefit='把餐次安排当可替换工具，不当挨饿考核。')
add('nutrition-004','别自行长期吃不足800千卡，快速减重需支持',
'每天只喝奶昔、吃水果或不吃饭不是医学减重。低于800千卡的极低能量方案需要特定适应情境、营养完整配方和临床监测，800至1200千卡也不是通用日常目标。开始前安排复查、用药和恢复普通食物，不只买产品饿下去。',
'NICE把每天低于800千卡称极低能量饮食，800至1200千卡也属需特定支持的低能量方案，不是所有成人日常推荐。特定肥胖或疾病情境可能用到，单想瘦快点不是充分理由。[@0][@1]\n\n正式方案要营养完整，先查用药和进食障碍风险，有临床支持；NICE要求这类方案不超过12周、逐步恢复多样食物并接长期支持，这不是自行挨饿12周的许可。蛋白粉果汁排毒茶不自动完整。[@0][@2]\n\n**开始前问清目的、监测者、何时复评或停止，以及恢复吃饭步骤。** 已长期几乎不进食、消瘦或持续乏力，先就医，不继续限制；掉发、疲劳等不是必须忍的代价，明显不适走[急症入口](#/entry/nutrition-001)。[@0][@1]',benefit='分清有医学支持的短期方案和营养不足的自行挨饿。')
add('nutrition-008','代餐先看营养是否完整，不拿青汁奶昔替全天',
'代餐的价值是方便和定量，不是自带燃脂作用。普通蛋白粉、青汁或零食棒不自动是完整一餐，全天只喝配方更需专业支持。买前看每份营养和过敏原、当天还吃什么，并约定用多久、谁随访和普通食物怎么恢复，不把无人监测的全代餐长期化。',
'“替一餐方便”和“全天配方饮食”是不同安排。普通奶昔、蛋白粉、青汁、棒的名称，不能证明营养完整，乘三份也不自动凑齐全天；减重作用看是否让总能量调整可持续，不是独立燃脂成分。[@0][@1]\n\n**偶尔图方便，查每份能量、蛋白、纤维、维矿及过敏原，连当天其余餐一起看。** 高蛋白不代表可长期省蔬果。全天用配方则先确认营养完整、疾病用药适合，并有专业长期支持。[@0]\n\n购买前安排能用多久、不适找谁、普通食物如何恢复、回升怎样处理；没有这些不长期无人监督全代餐。偏瘦、孕哺、进食障碍史、年长吃不够先营养评估。[@0][@1]',benefit='保留方便与定量价值，避免营养不完整的节食。')
add('nutrition-011','无糖饮料可替甜饮，不是额外喝就能减脂',
'常喝甜饮的人换成低无热量款，可作少糖过渡；本就喝水无需为减脂再加代糖饮料。成人替换试验有小幅体重收益，不证明比水更养生或长期必瘦。日常优先水、逐步少甜，看整份食品能量，不借无糖标签无限喝或多吃。',
'无糖饮料的比较对象很重要：成人试验综述中，用低无热量甜味饮料替甜饮，有小幅平均体重改善，不证明优于水或长期防病。[@0]\n\nWHO不建议把非糖甜味剂作长期控重主方法，这是有条件建议，长期观察可能有混杂；既有糖尿病管理、糖醇不在同一范围，也不是每次代糖致癌的结论。[@1]\n\n**原常喝甜饮可暂换低无热量款，本来喝水不必额外买。** 看有没有真正替掉糖和能量，核整份营养标签，不补偿性多吃。逐步减少总甜度，水和不加糖饮品作常用选择，不因无糖就无限吃点心。[@0][@1]',benefit='利用替换的实际价值，避免无糖营销或无依据恐慌。')
add('basics-007','补剂先有明确用途，服药手术前带齐清单',
'补剂可填缺口或服务特定用途，但天然、进口、高含量不保证对你有效安全。先列目标、成分、全天总量，连复合维生素和强化饮料一起算。服药、手术、孕哺先请医生药师核相互作用；质量认证也不等于疗效认证，不停处方迁就保健品。',
'补剂不是一律无效，也不因写抗氧化、天然或增强免疫就默认健康人获益；证据需对应人群、剂量和目标。第三方质量标识可帮助了解成分污染控制，不能保证适用疗效或绝对安全。[@0]\n\n**先说明想改善什么、有什么摄入缺口或已证用途，再买。** 把复合维生素、单方、强化食品和饮料总量算一起，防同成分重复；超需要可增加副作用，草本也可有强药理作用。[@0]\n\n服药、准备手术或孕哺，带名称成分、每日量和使用原因问接诊者或药师；如维生素K影响华法林，圣约翰草影响多药。不停处方来迁就补剂，不拿补剂代需治疗的病。[@0]',benefit='减少重复摄入、相互作用和为模糊宣称长期付费。')
add('nutrition-005','蛋白粉补实际缺口，不必赶练后半小时',
'蛋白粉是方便补蛋白的食品，不是增肌开关。先算蛋奶豆鱼肉等全天摄入与训练，吃不够再补，吃够后多灌不保证多长肌肉。按每份蛋白、配方和过敏耐受选择，不比桶大小；肾病、孕哺或医学营养需求另定方案，也别当完整代餐。',
'蛋白粉是补蛋白的便利用食。规律抗阻且摄入不足时，可增加平均肌肉力量收益；不训练或已经够，不因多几勺按比例变强。研究回归点不是人人精确上限，练后半小时也不是必须倒计时。[@0][@1]\n\n**把蛋奶豆鱼肉总量算进去，只补不足。** 看每份实际蛋白、配料、过敏和耐受；乳清、酪蛋白或合适植物蛋白可选，乳制品不适查乳糖或过敏，不硬喝。增肌粉可能加很多能量，和纯蛋白任务不同。[@0]\n\n前后能正常吃饭就分散日常、顾总量与恢复，不方便再用粉。肾病、孕哺、进食困难或医学营养需求，不照博主克数自配；蛋白粉不是完整代餐。[@0][@1]',benefit='让补充解决方便和缺口，减少时机焦虑与大桶溢价。')
add('nutrition-006','有力量训练再考虑一水肌酸，不追强制冲击期',
'肌酸帮助短时高强度供能，不是类固醇或减脂药。一水肌酸研究最多，其他贵变体不普遍更好；也不必强制先大量加载。早期增重可有肌肉水分，不能当长脂肪。按训练目标、配方和健康条件选择，肾病、孕哺或未成年不套成人方案。',
'肌酸参与肌肉快速能量周转，可辅助力量或重复短时高强度训练，不是类固醇或减脂药；耐力项目作用与体重代价另看。一水肌酸研究最多，贵盐类、缓冲或酯化形式未可靠证明普遍更好。[@0][@1]\n\n成人研究有不加载、每天约3至6克持续数周方案，说明不必大剂量冲击，不是人人自用处方。储量相近也不证明即时成绩相同，起效可较慢。[@2][@0][@3]\n\n**训练饮食基本到位再考虑，选单成分、量具清楚产品，按标签与运动营养方案。** 明显胃肠不适停并复评。早期增重可能有水分；健康运动者资料不支持常规补充必然伤肾，但不保证所有疾病产品安全。验血说明使用背景，不凭一次肌酐自判肾损或无事；肾病、孕哺等先核方案，儿童青少年不自行套用。[@0][@1]',benefit='保留适合训练的收益，避免误判水重或买昂贵变体。')
add('nutrition-007','完整蛋白吃够了，BCAA不必再加一桶',
'BCAA是亮氨酸、异亮氨酸和缬氨酸三种必需氨基酸，合成肌肉还需要其他原料。短时合成信号变强，不证明吃够完整蛋白后再补能长期多长肌肉。优先餐食和训练，酸痛减轻也不等于更强、更少受伤，更不能拿BCAA饮料替蛋白正餐。',
'BCAA是亮氨酸、异亮氨酸和缬氨酸三种支链必需氨基酸。肌肉合成不只需三种，完整蛋白本来就含它们；亮氨酸触发信号的原理，不能证明一瓶产品长期增肌。[@0][@1]\n\n10名年轻训练男性的小试验中，BCAA比安慰剂提高练后4小时蛋白合成，但没有完整蛋白同场对照、没看长期肌肉，不能证明吃够后还有增量。酸痛变化也不等于人人更强或更少受伤。[@2][@0]\n\n**预算先给训练、正常食物和足量完整蛋白；不足先补这些，已够不必再买第二桶。** 不把BCAA饮料当蛋白正餐，也不按网上安全上限反推应吃多少；疾病、孕哺和未成年另核。[@0]',benefit='把短时机制与实际长期增肌分开，减少无明确增量的叠加。')
add('nutrition-009','减重药用于健康需要，用前约好复查和维持',
'减重药能帮助合适人群，但不是正常体重瘦几斤的美容针。生活调整仍达不到健康目标时，可去体重管理或内分泌门诊，不必羞于用药。带病史、药单、生育计划，约好效果、不适和停换药随访，不能只看掉秤，更不先承诺必须终身用。',
'减重药是对有健康需要人群的治疗，不是正常体重再瘦几斤的美容用品。中国成人BMI24至不足28为超重、28及以上肥胖，但不等于每药的批准门槛，具体见[制剂人群与效果](#/entry/nutrition-017)。[@0][@1][@2]\n\n**生活方式认真调整仍达不到目标，可到体重管理或内分泌门诊。** 带体重腰围、吃动、全部药物补剂，以及糖尿病、胆囊胰腺、胃排空、甲状腺肿瘤家族史和生育计划。约定看体重腰围、疾病、进食、肌力及不良反应，不只追最低体重，老人尤其顾营养肌力。[@0][@1][@2][@3]\n\n开始前约复查、不适联系和停换药维持。部分需长期，也可因效果、安全、费用、生育调整；一盒非治愈，亦非人人终身。没效、吃不够或不耐受就调整，不强忍。安全见[风险与生育](#/entry/nutrition-018)，购买见[渠道核验](#/entry/nutrition-019)。[@0][@4]',benefit='让药物治疗有目标、有监测、有长期维持。',notes='')

add('nutrition-017','减重针先看中国适应证，比较效果别跨试验排榜',
'司美格鲁肽、替尔泊肽和玛仕度肽有随机试验支持，但具体中国制剂的用药门槛不同。比较平均减重先看直接对照，不能把不同人群、疗程的最大数拼排行榜。已有疾病、耐受、营养和长期执行也决定选择，靶点更多不等于更适合你。',
'GLP-1是调节食欲血糖的肠道激素；司美格鲁肽模拟其作用，减少饥饿进食。替尔泊肽同时作用GLP-1与GIP受体，玛仕度肽作用GLP-1与胰高血糖素受体，不是直接溶脂，靶点多不自动更安全。[@0][@1][@2]\n\n**证据比较要在同一研究内看。** SURMOUNT-5随机751名无2型糖尿病肥胖成人，平均起始113千克、BMI39.4，72周最大耐受方案下，替尔泊肽平均−20.2%、司美格鲁肽−13.7%；开放标签、礼来资助，常见胃肠不良反应。结果不保证正常体重、所有中国患者、每种剂量，亦非全面安全优效。[@4]\n\nGLORY-1为中国610名成人，平均87.2千克、BMI31.1；48周4/6毫克组−11.00%/−14.01%，安慰剂+0.30%，采用包含停药等情况的疗法策略分析，信达资助。它的人群疗程不同，不能同上横排“最强针”，研究剂量也不是加量处方。[@5]\n\n**按具体中国制剂判断是否可讨论治疗，不把BMI≥28的肥胖定义套所有药；均须配饮食活动。**[@0][@1][@2][@3]\n\n| 制剂 | 成人体重管理初始BMI | 选择时还要看 |\n| --- | --- | --- |\n| 司美格鲁肽注射液，诺和盈 | ≥30；或≥27至<30并有至少一种相关合并症 | 同成分糖尿病制剂不自动同用途；心血管病等另核疾病适应证 |\n| 替尔泊肽注射液，穆峰达 | ≥28；或≥24并有至少一种相关合并症 | 胃肠耐受、病史及具体说明书 |\n| 玛仕度肽注射液，信尔美 | ≥28；或≥24并有至少一种相关合并症 | 已核体重试验65岁及以上仅3人，不能套年轻人安全结论 |\n\n合并症可包括高血压、血脂异常、高血糖、阻塞性睡眠呼吸暂停等，逐制剂确认。已有心血管病糖尿病看疾病结局与适应证；反复吐、吃不够或年长体弱先顾营养耐受。有效耐受的方案不因排行榜自行换、叠针。[@3][@1][@2]',benefit='看清真实疗效与适用条件，不把平均减重当个人承诺。')
add('nutrition-018','减重药先查禁忌生育计划，严重腹痛视力骤降就医',
'减重药的禁用、慎用和监测要逐药确认，不靠一张通用表。持续重度腹痛、喝不进水少尿或突然视力丧失及时就医，喉舌肿喘不过气立即急救。备孕、哺乳、避孕药和麻醉需提前安排；恶心呕吐不代表燃脂更快，停药维持也应事先讨论。',
'**持续重度腹痛、尤其向背放射，停相关针剂并及时急诊；反复吐、喝不进水或明显少尿，及时就医；喉舌肿、呼吸困难立即急救。** 司美格鲁肽中国说明书有缺血性视神经病NAION警示，突然视力丧失立即眼科，不当干眼。轻恶心便秘也反馈，不硬忍加速加量。[@0][@1][@2]\n\n诺和盈、穆峰达、信尔美中国说明书均禁用于本人/家族甲状腺髓样癌或MEN2；后者是遗传性内分泌肿瘤综合征，不等于普通结节，但新结节肿块需查。动物警示不等于人已证实致癌，严重过敏亦逐药核。[@0][@1][@2]\n\n**首剂前带病史药单。** 胰腺炎、胆囊、胃排空或肝肾病并非全是绝对禁忌：诺和盈不建议重度胃轻瘫/重度肾损，穆峰达肾损不一概调量，但吐泻脱水可伤肾。糖尿病眼底病、胰岛素或磺脲类需眼底/血糖监测，不自停胰岛素、减药或叠GLP-1针。[@0][@1]\n\n备孕逐药计划：司美格鲁肽至少提前2个月停，玛仕度肽至少3个月，二者孕哺禁用；穆峰达减重孕期不应用，发现孕停止减重治疗并联系团队，不横套月份。**穆峰达加口服激素避孕药，改非口服或开始、每次加量后前4周加屏障避孕。** 此规则不自动套所有GLP-1药。孕哺替代方案逐药问。[@0][@1][@2]\n\n全麻、无痛胃肠镜等深镇静前，告知药名、末次日期、是否加量、恶心腹胀；药可延迟胃排空，禁食后仍可能有残留，由麻醉团队定继续、暂停或调整，不套一律停一周。[@0][@1][@2]\n\n停药回升不等于不自律或人人终身用。STEP-1的327人探索性延伸，停一年回升此前约三分之二，同时也撤掉结构化生活支持，不能说每人维持习惯仍必然如此。先约维持、复查、体重进食活动记录；无效、不耐受、吃不够就讨论换方案，年长体弱顾肌力营养。[@3][@4]',benefit='分清可调整不适、预先规划的风险与急需就医的信号。',notes='个人起始、加量、漏针和术前停药安排，按处方团队与手中制剂的现行说明书执行；少见严重反应的完整清单也需查具体药。')
add('nutrition-019','减重产品认准批准制剂，不买科研肽和分装针',
'药物、保健食品和试验中产品不是一类；发表论文、申请受理或海外上市，不代表手里这盒在中国获准减重。先核名称厂家批准文号，再看具体制剂说明书，通过正规渠道获取。奥利司他等老药也有适用范围与风险，科研粉、分装混合针不能借同名论文背书。',
'奥利司他减少部分膳食脂肪吸收，不是排出身上脂肪。国内非处方范本用于BMI≥24，首次仍要求咨询；不抵消糖酒或全部热量，吃油多更易油便、便急失禁，加量未证明更有效。孕期、慢性吸收不良、胆汁淤积禁用，哺乳和18岁以下不照成人方案。[@0]\n\n**用前查脂溶性维生素、相互作用和肾病结石史。** 环孢素、胺碘酮等先问；黄疸、深色尿、右上腹痛及时停药就医，非处方也有风险。利拉鲁肽通常日注、贝那鲁肽日多次，和周制剂负担不同；2026厂家公告先维盈（埃诺格鲁肽）获批成人体重管理，不代表新机制更优，同成分糖尿病制剂不自动可减重。[@1][@0][@2]\n\n购买按三步：\n\n1. 在[国家药监局](https://www.nmpa.gov.cn/datasearch/home-index.html)比药名、批准文号、企业；有同名记录仍不保证手中真品。\n2. 查这个品牌、剂型规格的中国现行说明书和适应证，不用外国标签、同成分别药、受理公告或入组标准代替。\n3. 正规医疗机构/有资质药房获取，处方药先评估并留凭证；包装破损、储运来源不明先问药师，不因药液透明就注射。[@3][@4][@5][@6]\n\n**不买科研/非人体标签多肽、原料粉、自兑或社群分装针。** 成分质量与剂量可错，论文不给来源不明瓶子背书，瑞他鲁肽研究针、混合肽亦然；盐型、浓度、笔装置不同，不按几格几滴单位互换。FDA警示不等于中国准入表。减肥咖啡糖果不替处方，我国已停西布曲明生产销售使用，勿试非法添加风险产品。[@7][@8]',benefit='保留合规治疗选择，分清获批药物与借同名营销产品。')
add('nutrition-010','排毒茶泻药不当减脂，燃脂丸先看成品证据',
'多排便、多出汗或短期体重降，不证明脂肪变少。排毒茶、利尿和泻药可致脱水、电解质问题；燃脂复配的机制或单成分研究也不能给整瓶保证。说不清对象、对照、时间、效果和总成分就先不买；严重不适停可疑品并带包装就医。',
'减重可来自水分、排便等，不能都算减脂。排毒茶、果汁清肠、泻药没因此证明长期去脂或清毒，只喝茶不吃饭还可脱水、电解质紊乱；便秘应按便秘治。[@0]\n\n燃脂丸、左旋肉碱复配、育亨宾、绿茶提取或高咖啡因，需看具体成分及成品人体证据。小样本短期、单成分或促脂肪代谢机制，不能保证复配瓶长期有效；刺激高浓缩成分也有相互作用等风险。[@1]\n\n**买前问研究人群、对照、多久、改善多少和总量，说不清就不买。** 明显心悸、胸痛、晕厥、持续吐或严重不适，停可疑产品及时就医并带包装；不为排毒停处方，真正中毒的医疗处理另属一事。[@0][@1]',benefit='不为水分变化和模糊机制支付长期减脂费用。')

add('activity-001','运动中胸痛或晕倒，立即停下并按急症处理',
'胸部压迫痛不缓解，或伴气短、冷汗、恶心、头晕、向手臂下颌放射，停活动并拨120。运动中晕倒即使醒来好些也应立即急救评估，不自驾、不再跑一段试验。手表心率正常不能排除危险；反复运动不适也要先查原因。',
'**胸部压迫、紧缩或痛未很快缓解，或伴气短、出汗、恶心、头晕、向手臂下颌扩散，立即停活动、拨120。** 在安全处休息、请旁人帮忙，不自驾、不等手表报警，不继续跑来试是否没事。胸痛可来自肌肉或心肺，轻重不能在家分清。[@0]\n\n**运动过程中晕倒，即使已醒也立即拨120、紧急评估。** 无反应或呼吸异常，旁人按调度指导施救，不一概当低血糖、体能差或中暑。[@1]\n\n无上述急症，但反复运动胸部不适、心悸或快晕倒，停诱发训练并就诊，记录项目、时长、伴随症状及药物。是否返练看原因，不靠站得起来或手表正常证明；一般分流见[胸痛](#/entry/chest-001)。[@1][@0]',benefit='不让设备读数或短暂好转延误运动急症。')
add('activity-002','热天运动先减量，意识异常立即急救并降温',
'高温闷热先改凉快时段、缩短减轻训练并逐渐适应。头晕恶心乏力就停，到凉处降温；意识混乱、说话异常、走不稳、抽搐或昏迷，立即拨120并持续降温。热射病仍可能出汗，别等体温计或无汗才行动，也别给意识异常者灌水。',
'**高温中意识混乱、言语不清、走不稳、抽搐或失去意识，立即拨120，同时降温。** 移阴凉处、脱多余衣物，凉水湿皮扇风，或安全可行时尽快浸水降温；等救护车也不停，不等温度计，不给疑似热射病者喝东西。[@0][@1]\n\n热射病是危及生命的高温重症，皮肤可干也可大汗，不能凭出汗排除。仅头痛、恶心、头晕、乏力或大汗也停练降温；清醒能吞咽可小口水，安排医疗评估。恶化、反复吐或意识协调异常转急救，不独处或自驾。[@0][@1]\n\n**预防靠避热、低于平常量起步逐渐适应、轻便透气穿着和同伴观察。** 感到虚弱要晕即停，不跟配速硬撑；电解质水不能抵消持续热中训练。[@2]',benefit='分清热天减量、早停和重症急救，不只靠补水。')
add('activity-003','练后异常剧痛、无力或茶色尿，立即就医',
'猛增训练后，疼痛远超平常、无力到做不了原能做的事，或茶色可乐色尿，不当练得有效。横纹肌溶解可伤肾，症状可能延迟数小时数日，三种不必齐全。停训到凉处并立即求医，不靠强灌水、尿试纸或等次日缓解代替检查。',
'**异常剧烈肌痛痉挛、明显无力或茶色可乐色尿，出现一种就应立即求医，不等三种齐全。** 停训练、到凉处尽快急诊，严重或不能安全前往拨120；症状可在运动后数小时至数天才出现。[@0][@1]\n\n横纹肌溶解是肌肉损伤后细胞内容物大量入血，可造成肾和电解质危险，不是普通酸痛。尿正常或一次试纸不能排除，常需血液肌酸激酶等检查。[@0][@1]\n\n带运动、突增负荷、高温暴露、发作时间和药补清单。是否口服、静脉补液或住院看严重度，不大量灌水替代就医，不当天换肌群继续；恢复训练等医疗评估，普通酸痛见[恢复](#/entry/activity-005)。[@1]',benefit='为少见但严重的训练损伤提供及时就医入口。')
add('basics-006','活动从小量开始，有氧、力量和平衡分别安排',
'不必办卡或练到力竭才算开始。成人从能持续的小量活动做起，逐步接近每周150分钟中等或75分钟较高强度，再加至少两天力量。65岁以上还要顾平衡灵活性；久坐穿插走动，慢病疼痛和孕产恢复另调，不硬顶统一计划。',
'有氧活动和力量训练不是同义词：快走骑车练耐力，合适自重、弹力带等练主要肌群。NHS对19—64岁每周参考至少150分钟中等或75分钟较高强度，并至少2天力量；中等强度约能说话但难唱歌。[@0]\n\n**从现在能承受的小量开始，逐步增加频率、时长和强度，不必马上达标或每次连续很久。** 久坐间隙走动，不先买高价器械。[@0]\n\n65岁以上加入平衡、力量和灵活性；跌倒史者配安全支撑及指导。长期不动、心肺病、疼痛等先定合适强度，孕产恢复另调。胸痛晕厥不硬练，成人时长不套儿童或康复处方。[@1]',benefit='把活动落实到能持续的日程，而非统一高强度打卡。')
add('activity-004','运动前渐进热身，结束放慢，不靠强拉伸防伤',
'热身可用目标运动的慢速版，如快走前慢走、跑前走跑渐进；结束也逐渐降速。5至10分钟只是一般入门例子，按项目身体调整。拉伸到温和牵拉即可，不弹震硬压；它有柔韧用途，却不保证防伤，也不能显著消除次日酸痛。',
'热身是以较轻版本进入后续活动，慢走渐到快走、走和慢跑渐到计划配速；美国心脏协会的5—10分钟是一般示例，不是统一精确剂量。[@0]\n\n拉伸可改善柔韧等，但健康成人综述未见运动前后拉伸有临床意义的酸痛减轻；不是必须完成的排酸任务，也不能保证防伤或抵消突然翻倍的训练量。[@1]\n\n**开始逐步提速与扩大活动幅度，结束由跑转走逐渐放慢。** 拉伸限温和牵拉，不弹震、不痛拉、不请人强压；按恢复调整下一次负荷，不为热身或排酸买齐设备。[@0][@1]',benefit='用简单过渡进入和结束运动，减少强拉伸的错误期待。')
add('activity-009','力量动作练稳再加难度，不必每组都力竭',
'抗阻训练是让肌肉对抗阻力，自重、弹力带、哑铃或器械都能用。先把动作和负荷控制好，变轻松再逐步加，不同时猛加重量总量频率。每组练到做不动不是必需，酸痛和贵器械也不是进步门票；衰弱、慢病、术后疼痛需另定范围。',
'力量或抗阻训练是让肌肉对抗身体重量、弹力带、哑铃或器械。2026 ACSM汇总137篇综述，支持健康成人渐进训练，家庭和多种工具都可获益，不必先买齐器材。[@0]\n\n力竭是一组无法再完成下一次合格动作；普通健康成人未被证明普遍需每组力竭，也无人人最佳“保留几次”。动作变形、憋到失控或次日痛，不是有效的必要条件。[@0]\n\n**选能稳定控制的阻力和范围，简单记录；明显变轻松再逐步改阻力、次数或难度，不同时猛加重量、总量、频率。** 资料主要为健康成人及部分健康老人，明显衰弱、术后、心肺病、疼痛康复和儿童需适龄、个体化动作负荷与监督，不套固定组数表。[@0]',benefit='降低器材门槛，以渐进挑战而非失控证明训练。')
add('activity-005','练后酸痛就调负荷，异常剧痛无力别硬练',
'新动作或较强运动后1至3天酸痛常见，但疼不疼不能判断练得好不好。温和活动或换部位，同一酸痛肌群先别冲极限，恢复日常能力后再加。突然锐痛、很重、明显肿胀或不能用，先就医；茶色尿或异常无力按横纹肌溶解警讯处理。',
'延迟性肌肉酸痛（DOMS）是不熟悉或较强运动后才出现的酸胀，常1—3天明显，不是训练当时的突然锐痛。酸痛不等于必须撕裂更狠才长肌肉，进步看一段时间的动作、力量与能力。[@0][@1]\n\n**保留不加重不适的轻活动或练其他部位，酸痛肌群先不高强度、长时间或冲极限。** 日常动作恢复后逐步加，不猛练补休息日；拉伸未可靠证明能明显消除这种酸痛，不必买排酸套装。[@0][@2]\n\n突然锐痛、很重、明显肿或不能正常用，停下就医；约一周无改善也评估。异常无力或茶色可乐尿按[横纹肌溶解](#/entry/activity-003)立即求医，不因按摩热敷舒服就认定安全恢复。[@0][@1][@3]',benefit='按恢复持续训练，不把追求疼痛当目标。')
add('activity-006','普通短练先喝水，长时高负荷再考虑运动饮料',
'运动饮料要分补水、补盐和补碳水，普通短时活动通常水加正常吃饭就够。超过约一小时耐力或数小时大量汗可考虑，但不是过线必喝；看天气、强度、饮食和耐受，比赛前先试。无糖款不补碳水，能量饮料不是补液，水和饮料过量都可能危险。',
'电解质包括钠等维持体液和神经肌肉功能的物质；运动饮料通常有水、电解质和碳水，但配方不同。无糖款可补液盐，不提供碳水燃料，高咖啡因能量饮料也不是同一类。[@0][@1]\n\n**普通短练多用水与正常进餐；持续较久中高强度，如超过约一小时耐力，或数小时大量汗，再按需要考虑运动饮料。** 还看热度、出汗、是否进食和胃肠耐受，先训练试，不比赛当天突换。[@2][@0][@3]\n\n看标签碳水、糖和钠，不信“离子补能”字样；多加镁不自动更防抽筋。不要为固定升数短时猛灌，水和运动饮料过量都可危险低钠。心衰、慢肾病、限水者按医疗方案，也不能拿饮料治热射病或横纹肌溶解。[@1][@3][@4]',benefit='减少无必要饮料、额外糖和过量饮水，按运动需要补。')
add('activity-007','手表热量只作估计，身体不适别等报警',
'手表可记时间和趋势，不是精确的加餐额度或安全证明。心率准确性受设备和活动影响；普通有氧也用体感，能说话难唱歌约是中等强度。胸痛、快晕或运动晕厥先停练就医，即使读数正常也不继续；旧设备研究不能给当前新品排榜。',
'手表消耗千卡是算法估计，不是直接量热。60名健康年轻人、五类活动的三旧型号验证中，能量估计不够准，心率也随活动设备变；不能据此排2026新品，但不宜精确吃回显示热量。[@0]\n\n**用同一设备记时间、习惯和趋势，普通有氧也看体感。** 中等强度通常能说话难唱歌，高强度说几词需换气；谈话测试不是心脏检查或力量公斤标准。[@1]\n\n胸痛、快晕或运动晕厥按[急症](#/entry/activity-001)停练求助，不等报警、不再练试安全。特定医疗功能不让所有运动曲线都具诊断能力；已确诊疾病按自己的运动方案用设备。[@2][@3][@0]',benefit='保留记录习惯的价值，减少对算法与正常读数过度依赖。')
add('activity-008','空腹训练不保证多减脂，不舒服就调整吃练',
'空腹时多用脂肪供能，不等于几周后一定少更多体脂。现有研究小而结果不一，不足以要求人人早餐前练。恶心头晕乏力、训练明显掉量就换更舒适吃练安排，不硬撑。胰岛素或易低血糖药使用者，先安排饮食监测用药，不自行省餐加练。',
'空腹训练通常是隔夜未进食后练。当次多用脂肪不等于长期多减脂：20名年轻女性四周同训练限能量试验，未见明确体成分优势，不足以证明严格等效。2025力量综述仅四研究、三高偏倚，肌量力量无明确差，脂肪有偏向空腹信号，仍不能要求人人采用或断言绝无额外作用。[@0][@1]\n\n**按能否舒服完成、长期吃练决定时点。** 空腹恶心、头晕、乏力或训练量明显下降，就改进食后合适时间，不硬撑；能舒服坚持也不必为时点打乱睡眠饮食。胸痛晕厥按[急症](#/entry/activity-001)，不当普通空腹反应。[@0][@1][@2][@3]\n\n胰岛素或促胰岛素分泌的降糖药，漏餐加运动会增加低血糖风险；先与照护团队定进食、监测、运动和药物计划，不自行减药省餐。[@4]',benefit='减少空腹时点的强迫，把稳定训练与用药安全放前面。')
add('basics-003','疲劳持续数周或影响生活，带记录查原因',
'偶尔累先回顾睡眠、饮食、负荷和近期生病；持续数周、原因不明或已影响生活，就安排评估。体重降、心悸气短、口渴尿多、鼾憋和情绪变化一起说。检查按病史选择，不人人全查激素维生素，补剂提神也不能代替查原因。',
'疲劳可由身体、心理和生活处境共同影响，喝咖啡后感觉好不代表原因解决。医生可能按线索考虑贫血、糖尿病、甲状腺等，不是每人照单全查维生素激素。[@0]\n\n**持续数周、原因不明或影响生活，到全科或相关门诊，带睡眠、感染、工作照护负荷、吃饭变化和完整药补酒精清单。** 说清体重、心悸气短、口渴尿多、鼾憋和情绪变化。[@0]\n\n不未明需求就补铁，过量可有害；初检无明显异常仍可讨论睡眠、药物、情绪和复评，不归咎装病或意志差。突胸痛、重气短、晕厥或新神经症状另急救。[@0][@1]',benefit='让评估有方向，减少用大套餐和提神补剂代替病史。')
add('energy-002','轻活动后隔天垮掉，先评估，别硬加训练量',
'轻体力或脑力活动后，反复延迟到隔天加重，伴疲劳脑雾睡眠问题、拖数日，不一概归缺锻炼。记录活动和症状时间，先拆小任务、交替休息，不因稍好补做大量活动。需要评估，不能自己确诊慢性疲劳综合征；急胸痛气短晕厥仍先急救。',
'活动后不适（PEM）是轻身体或脑力活动后，一组症状明显加重、可迟发数日，和局部运动酸痛不同。它是评估线索，不是疲劳就能自行确定的病名。[@0]\n\n**反复出现时，先别强推固定递增训练。** 记做什么、多久、何时加重和怎样恢复，带到全科或相关门诊；评估前按耐受拆小任务，交替活动休息，不在稍好时补完，也不要求人人完全不动。[@0]\n\n确诊ME/CFS（肌痛性脑脊髓炎/慢性疲劳综合征）需个体化活动，不套健康训练目标。突发胸痛、明显气短或晕厥先按[急症](#/entry/chest-001)，日记不能代替急救。[@0]',benefit='识别不能照搬训练进阶的情境，保留活动与症状的时间线。')
add('energy-001','提神先算全天咖啡因，心悸失眠别继续叠加',
'把咖啡、茶、能量饮料、训练前补剂和相关药物的每份量合计，不按几杯猜。400mg是多数成人每日参考，不是必须吃满或人人安全线。心悸手抖失眠就停止叠加，胸痛晕厥按急症；不买纯粉浓缩液用厨勺配，儿童孕哺和用药者另有条件。',
'咖啡因可来自咖啡茶、能量饮料、训练补剂和药物，天然来源也计入。FDA每日400mg是多数成人参考，不保证敏感或基础病者没影响，低咖也未必零咖啡因。[@0]\n\n**查每份毫克乘实际份数，合计所有来源；没标可查官方资料或问商家，不靠杯数猜。** 已心悸、恶心、手抖、失眠就停止继续加并求助，胸痛晕厥或严重不适按[急症](#/entry/chest-001)。孕哺备孕及合并用药先问个人限制，儿童青少年不靠能量饮料提神。[@0]\n\n困倦需要睡眠与查因，不用咖啡证明能[安全开车](#/entry/sleep-001)。不买纯粉或高浓缩液用厨房勺配，长期想减可逐渐减少。[@1][@0]',benefit='减少隐形叠加和浓缩误量，不用提神继续侵占睡眠。')
add('basics-009','别为养生喝酒吸烟，已有依赖先安全减停',
'红酒药酒和低焦草本电子烟，都不是应为健康新开始的习惯。产品风险有差别，不等于无害；吸烟可找正规戒烟支持。长期大量喝酒，停后手抖出汗先评估戒断，不自行骤停或换酒顶；幻觉、严重震颤、抽搐立即急救。',
'烟草伤多个器官，电子烟也非健康用品；不同产品可有风险差异，少害不等于无害，也不等于全部一样。酒即使少量仍有风险，红酒药酒的某种成分不能成为开始喝的理由。[@0][@1][@2]\n\n**不为养生新增烟、电子烟或酒精；吸烟者可到戒烟门诊讨论行为支持和合适药物。** 已饮酒者减少量、避免一次大量可降部分风险，不把任何杯数当零风险。[@0][@2]\n\n长期大量喝、停后手抖出汗恶心，先到全科、精神科或成瘾服务计划安全减停，依赖者骤停可危险；幻觉、严重震颤、抽搐立即急救，不换酒或自买镇静药。[@3]',benefit='避免营销新增暴露，让依赖问题获得安全支持。')
add('basics-008','情绪注意力持续受影响就求助，不必等体检异常',
'睡眠、疾病、药物、压力和生活处境都能影响情绪与注意力，不全是身体差或不自律。持续低落焦虑、失去兴趣，严重或影响生活就可评估，不先等满两周或体检异常。无法保证自身安全时立即找急救，并请可信任的人陪同，别等养生起效。',
'身体和心理相互影响，睡眠、疾病、药物、生活处境都可能参与情绪与注意力变化；不能只归身体差或意志不够，也不必等化验异常才求助。[@0]\n\n**持续低落、焦虑、失去兴趣或注意困难，严重或已影响生活，就联系全科、心理或精神科。** 两周等提示不是必须忍满的等待期，文章和生理指标都不能自诊。[@0]\n\n有伤害自己的念头、已受伤或不能确保安全，立即联系当地急诊急救，请可信任者陪同，不等作息、日晒、聊天或补剂起效。[@0]',benefit='保留必要求助入口，不让单一身体指标拖延评估。')

def finish():
    assert set(edits)==set(by_id),(len(edits),set(by_id)-set(edits))
    edits['sleep-011']['fields']['plain']=edits['sleep-011']['fields']['plain'].replace('睡前停手机的小试验有部分改善，样本小且受监督；夜间模式试验未见总体睡眠改善','38名睡眠较差大学生的四周停手机试验有部分改善，样本小且受监督；167名年轻成人的七夜夜间模式试验未见总体睡眠改善')
    edits['nutrition-015']['fields']['plain']=edits['nutrition-015']['fields']['plain'].replace('小型糖尿病综述未确立标准饮食外的额外长期收益','2型糖尿病小型试验综述未确立标准饮食外的额外长期收益，证据确定性较低')
    natural={'复评':'重新评估','药补清单':'药物和补充剂清单','全药单':'完整用药清单','不困驾':'别犯困时开车','日困':'白天犯困','热中训练':'在高温中训练','重度肾损':'重度肾功能损害','穆峰达肾损':'穆峰达的肾功能损害','肾损不一概调量':'肾功能损害不一定需要调整剂量','停自行加量':'停止自行加量','不自停减':'不自行停药或减量','先核方案':'先确认方案','药量都不能':'用药量都不能'}
    for n in edits.values():
        for k in ['plain','benefit','notes']:
            for before,after in natural.items():n['fields'][k]=n['fields'][k].replace(before,after)
    output=[];audit=[]
    for e in original:
        n=edits[e['id']]
        assert 60<=len(n['summary'])<=140,(e['id'],len(n['summary']))
        old_refs=set(re.findall(r'\[@([^\]]+)\]','\n'.join(e['fields'].values())))
        new_refs=set(re.findall(r'\[@([^\]]+)\]','\n'.join(n['fields'].values())))
        assert old_refs==new_refs,(e['id'],old_refs-new_refs,new_refs-old_refs)
        assert n['title']!=e['title'] and n['summary']!=e['summary'] and n['fields']['plain']!=e['fields']['plain'],e['id']
        assert len(n['fields']['plain'])>=80,e['id']
        def clinical_nums(text):
            text=re.sub(r'\[@[^\]]+\]|\]\(#/entry/[^)]+\)','',text)
            return set(re.findall(r'\d+(?:\.\d+)?',text))
        removed=sorted(clinical_nums(e['fields']['plain'])-clinical_nums(n['fields']['plain']))
        assert not removed,(e['id'],removed)
        record=dict(id=e['id'],original_fields_sha256=hashlib.sha256(json.dumps(e['fields'],ensure_ascii=False,sort_keys=True).encode()).hexdigest(),all_fields_read=True,title_rewritten=True,summary_rewritten=True,plain_rewritten=True,source_ids_preserved=sorted(old_refs),original_plain_chars=len(e['fields']['plain']),new_plain_chars=len(n['fields']['plain']),audience_unchanged=True,evidence_and_source_fields_unchanged=n['fields']['evidence']==e['fields']['evidence'] and n['fields']['sources']==e['fields']['sources'],numeric_tokens_removed=removed,numeric_review='移除引用hash与内部链接ID后逐条比对阿拉伯数字，原正文数值均保留；并手读保留单位、比较方向、时点与非统一阈值/适应人群条件。数字一致不是语义正确的自动证明。')
        n['audit'].update(record);output.append(n);audit.append(record)
    (HERE/'body-rewrites.json').write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    report=dict(scope='124条全部字段逐条阅读与表达重写；不是重新医学系统综述或临床签审。',entries=len(output),original_plain_chars=sum(x['original_plain_chars'] for x in audit),new_plain_chars=sum(x['new_plain_chars'] for x in audit),checks=audit,blocking_unresolved=[],clinical_review_status='not_clinically_reviewed')
    (HERE/'body-audit.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({k:report[k] for k in ['entries','original_plain_chars','new_plain_chars']}))

